-- BEGIN file: 00_extensions_and_types.sql
-- ============================================================================

-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - MULTI-TENANT POSTGRESQL SCHEMA
-- ============================================================================
-- File: 00_extensions_and_types.sql
-- Description: PostgreSQL extensions and custom enum types
-- ============================================================================

-- Required Extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";       -- UUID generation
CREATE EXTENSION IF NOT EXISTS "pgcrypto";         -- Password hashing / encryption
CREATE EXTENSION IF NOT EXISTS "btree_gin";        -- GIN index support for scalars
CREATE EXTENSION IF NOT EXISTS "pg_trgm";          -- Trigram similarity for text search

-- ============================================================================
-- CUSTOM ENUM TYPES
-- ============================================================================

-- Tenant / Subscription
CREATE TYPE tenant_status AS ENUM ('active', 'inactive', 'suspended', 'trial');
CREATE TYPE billing_period AS ENUM ('monthly', 'quarterly', 'yearly');

-- User & Auth
CREATE TYPE user_status AS ENUM ('active', 'inactive', 'locked', 'deleted');
CREATE TYPE user_type AS ENUM ('local', 'oauth', 'ldap', 'idp', 'lockbox');
CREATE TYPE identity_provider_type AS ENUM ('local', 'google', 'github', 'microsoft', 'ldap', 'saml', 'entra');
CREATE TYPE jwt_algorithm AS ENUM ('RS256', 'RS384', 'RS512', 'ES256', 'ES384');
CREATE TYPE audit_change_type AS ENUM ('CREATE', 'UPDATE', 'DELETE', 'LOGIN', 'LOGOUT', 'LOCK', 'UNLOCK', 'PASSWORD_CHANGE', 'ROLE_CHANGE', 'PERMISSION_CHANGE', 'EXPORT', 'IMPORT', 'ACTIVATE', 'DEACTIVATE');
CREATE TYPE mfa_method AS ENUM ('totp', 'sms', 'email', 'backup_code');

-- Academic
CREATE TYPE gender_type AS ENUM ('male', 'female', 'other');
CREATE TYPE blood_group_type AS ENUM ('A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-', 'unknown');
CREATE TYPE document_type AS ENUM ('birth_certificate', 'transfer_certificate', 'medical', 'report_card', 'id_proof', 'photo', 'other');

-- Attendance
CREATE TYPE attendance_status AS ENUM ('present', 'absent', 'late', 'half_day', 'holiday', 'excused');
CREATE TYPE leave_type AS ENUM ('sick', 'casual', 'earned', 'maternity', 'paternity', 'unpaid', 'other');
CREATE TYPE leave_status AS ENUM ('pending', 'approved', 'rejected', 'cancelled');
CREATE TYPE verification_mode AS ENUM ('fingerprint', 'face', 'card', 'manual');

-- Examination
CREATE TYPE exam_type AS ENUM ('unit_test', 'quarterly', 'half_yearly', 'annual', 'preliminary', 'practice', 'other');

-- Finance
CREATE TYPE fee_type AS ENUM ('tuition', 'admission', 'library', 'transport', 'hostel', 'laboratory', 'sports', 'examination', 'miscellaneous');
CREATE TYPE fee_frequency AS ENUM ('one_time', 'monthly', 'quarterly', 'half_yearly', 'annual');
CREATE TYPE payment_mode AS ENUM ('cash', 'card', 'online', 'bank_transfer', 'cheque', 'upi');
CREATE TYPE payment_status AS ENUM ('pending', 'completed', 'failed', 'refunded', 'partial');
CREATE TYPE alert_type AS ENUM ('sms', 'email', 'push', 'whatsapp');

-- Communication
CREATE TYPE notification_channel AS ENUM ('sms', 'email', 'push', 'in_app', 'whatsapp');
CREATE TYPE notification_status AS ENUM ('queued', 'sent', 'delivered', 'failed', 'read');
CREATE TYPE priority_level AS ENUM ('low', 'medium', 'high', 'urgent');

-- Transport
CREATE TYPE vehicle_status AS ENUM ('active', 'maintenance', 'retired', 'inactive');

-- Library
CREATE TYPE book_issue_status AS ENUM ('issued', 'returned', 'lost', 'damaged', 'renewed');

-- HR
CREATE TYPE payroll_status AS ENUM ('draft', 'processed', 'paid', 'cancelled');

-- Timetable
CREATE TYPE day_of_week AS ENUM ('monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday');
CREATE TYPE material_type AS ENUM ('pdf', 'video', 'assignment', 'presentation', 'link', 'other');
CREATE TYPE homework_status AS ENUM ('draft', 'published', 'closed');

-- Administration
CREATE TYPE room_type AS ENUM ('dormitory', 'shared', 'private');
CREATE TYPE asset_status AS ENUM ('available', 'in_use', 'maintenance', 'disposed');
CREATE TYPE complaint_priority AS ENUM ('low', 'medium', 'high', 'critical');
CREATE TYPE complaint_status AS ENUM ('open', 'in_progress', 'resolved', 'closed', 'escalated');
CREATE TYPE inventory_category AS ENUM ('furniture', 'electronics', 'stationery', 'sports', 'laboratory', 'cleaning', 'other');

-- Approval
CREATE TYPE approval_status AS ENUM ('pending', 'approved', 'rejected');


-- ============================================================================
-- END file: 00_extensions_and_types.sql
-- ============================================================================


-- ============================================================================
-- BEGIN file: 01_platform_and_tenant.sql
-- ============================================================================

-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - PLATFORM & TENANT TABLES
-- ============================================================================
-- File: 01_platform_and_tenant.sql
-- Description: Subscription plans, tenants, and tenant settings
-- ============================================================================

-- ============================================================================
-- SUBSCRIPTION PLANS  (platform-level, not tenant-scoped)
-- ============================================================================

CREATE TABLE subscription_plans (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name            VARCHAR(100) NOT NULL,                         -- Basic / Premium / Enterprise
    billing_period  billing_period NOT NULL DEFAULT 'monthly',
    price           NUMERIC(12,2) NOT NULL CHECK (price >= 0),
    max_students    INTEGER,                                       -- NULL = unlimited
    max_users       INTEGER,
    max_storage_gb  INTEGER,
    features        JSONB NOT NULL DEFAULT '{}',                   -- { "sms": true, "biometric": false, ... }
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE subscription_plans IS 'Defines available subscription tiers for tenants';

-- ============================================================================
-- TENANTS  (each school is a tenant)
-- ============================================================================
CREATE TABLE tenants (
    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name                    VARCHAR(255) NOT NULL,
    subdomain               VARCHAR(63) NOT NULL UNIQUE,            -- {subdomain}.erp.com
    slug                    VARCHAR(100) NOT NULL UNIQUE,
    logo_url                TEXT,
    timezone                VARCHAR(50) NOT NULL DEFAULT 'Asia/Kolkata',
    country                 VARCHAR(100),
    state                   VARCHAR(100),
    city                    VARCHAR(100),
    address                 TEXT,
    pincode                 VARCHAR(20),
    contact_email           VARCHAR(255),
    contact_phone           VARCHAR(30),
    website                 VARCHAR(255),
    status                  tenant_status NOT NULL DEFAULT 'trial',
    subscription_plan_id    UUID REFERENCES subscription_plans(id),
    subscription_start_date DATE,
    subscription_end_date   DATE,
    trial_ends_at           TIMESTAMPTZ,
    api_key                 VARCHAR(255) UNIQUE,                    -- tenant-level API key
    metadata                JSONB NOT NULL DEFAULT '{}',
    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at              TIMESTAMPTZ,                            -- soft delete

    CONSTRAINT chk_subdomain_format CHECK (subdomain ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$'),
    CONSTRAINT chk_subscription_dates CHECK (subscription_end_date IS NULL OR subscription_end_date >= subscription_start_date)
);

COMMENT ON TABLE tenants IS 'Each row represents a school (tenant). All child data is scoped by tenant_id.';
COMMENT ON COLUMN tenants.subdomain IS 'Unique subdomain used in URL: {subdomain}.erp.com';
COMMENT ON COLUMN tenants.api_key IS 'API key for external integrations; rotated periodically';

-- ============================================================================
-- TENANT SETTINGS
-- ============================================================================
CREATE TABLE tenant_settings (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    session_timeout_min INTEGER NOT NULL DEFAULT 30 CHECK (session_timeout_min > 0),
    max_users           INTEGER,
    max_students        INTEGER,
    academic_year_format VARCHAR(20) DEFAULT 'YYYY-YYYY',           -- e.g. 2025-2026
    date_format         VARCHAR(20) DEFAULT 'DD/MM/YYYY',
    currency_code       VARCHAR(3) DEFAULT 'INR',
    grading_system      VARCHAR(20) DEFAULT 'percentage',           -- percentage / gpa / grade
    attendance_mode     VARCHAR(20) DEFAULT 'manual',               -- manual / biometric / both
    sms_gateway         VARCHAR(50),
    email_provider      VARCHAR(50),
    features_enabled    JSONB NOT NULL DEFAULT '{}',                 -- { "transport": true, "hostel": false, ... }
    theme               JSONB NOT NULL DEFAULT '{}',                -- { "primary_color": "#1976D2" }
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE tenant_settings IS 'Per-tenant configuration; one row per tenant';


-- ============================================================================
-- END file: 01_platform_and_tenant.sql
-- ============================================================================


-- ============================================================================
-- BEGIN file: 02_users_and_rbac.sql
-- ============================================================================

-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - USERS & RBAC
-- ============================================================================
-- File: 02_users_and_rbac.sql
-- Description: Users, roles, permissions, and role/permission assignments
-- ============================================================================

-- ============================================================================
-- ROLES  (seeded per tenant + platform-wide Super Admin)
-- ============================================================================
CREATE TABLE roles (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id   UUID REFERENCES tenants(id) ON DELETE CASCADE,   -- NULL = platform-wide role (Super Admin)
    name        VARCHAR(100) NOT NULL,
    slug        VARCHAR(100) NOT NULL,
    description TEXT,
    is_system   BOOLEAN NOT NULL DEFAULT FALSE,                     -- system roles cannot be deleted
    is_active   BOOLEAN NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_role_per_tenant UNIQUE (tenant_id, slug)
);

COMMENT ON TABLE roles IS 'RBAC roles. tenant_id = NULL means platform-level (Super Admin).';
COMMENT ON COLUMN roles.is_system IS 'System-seeded roles (Admin, Teacher, Student, etc.) cannot be deleted';

-- ============================================================================
-- PERMISSIONS  (module-level granular permissions)
-- ============================================================================
CREATE TABLE permissions (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    module      VARCHAR(100) NOT NULL,                              -- e.g. students, finance, attendance
    action      VARCHAR(50) NOT NULL,                               -- view, create, edit, delete, export, approve
    description TEXT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_permission UNIQUE (module, action)
);

COMMENT ON TABLE permissions IS 'Granular module-level permissions (view/create/edit/delete/export)';

-- ============================================================================
-- ROLE â†” PERMISSION MAPPING
-- ============================================================================
CREATE TABLE role_permissions (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    role_id       UUID NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
    permission_id UUID NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_role_permission UNIQUE (role_id, permission_id)
);

-- ============================================================================
-- USERS  (tenant-scoped; created offline / imported)
-- ============================================================================
CREATE TABLE users (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID REFERENCES tenants(id) ON DELETE CASCADE,  -- NULL = super admin
    username            VARCHAR(150) NOT NULL,
    email               VARCHAR(255),
    password_hash       VARCHAR(255) NOT NULL,
    first_name          VARCHAR(100) NOT NULL,
    last_name           VARCHAR(100),
    phone               VARCHAR(30),
    avatar_url          TEXT,
    status              user_status NOT NULL DEFAULT 'active',
    is_super_admin      BOOLEAN NOT NULL DEFAULT FALSE,
    email_verified_at   TIMESTAMPTZ,
    last_login_at       TIMESTAMPTZ,
    password_changed_at TIMESTAMPTZ,
    created_offline_at  TIMESTAMPTZ,                                      -- when the record was prepared offline
    imported_by         UUID REFERENCES users(id),                     -- user who performed CSV/Excel import
    import_batch_id     VARCHAR(100),                                     -- batch identifier for bulk imports
    metadata            JSONB NOT NULL DEFAULT '{}',
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at          TIMESTAMPTZ,                                      -- soft delete

    CONSTRAINT uq_user_per_tenant UNIQUE (tenant_id, username),
    CONSTRAINT uq_email_per_tenant UNIQUE (tenant_id, email)
);

COMMENT ON TABLE users IS 'All platform and tenant users. Created via offline import (CSV/Excel), not self-registration.';
COMMENT ON COLUMN users.tenant_id IS 'NULL for platform-level super admins; otherwise the school this user belongs to';
COMMENT ON COLUMN users.created_offline_at IS 'Timestamp from the offline source (CSV/Excel row creation time)';

-- ============================================================================
-- USER â†” ROLE ASSIGNMENT
-- ============================================================================
CREATE TABLE user_roles (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role_id     UUID NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
    assigned_by UUID REFERENCES users(id),
    assigned_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_user_role UNIQUE (user_id, role_id)
);

-- ============================================================================
-- USER â†” PERMISSION OVERRIDE  (grant/deny beyond role defaults)
-- ============================================================================
CREATE TABLE user_permissions (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    permission_id UUID NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,
    is_granted    BOOLEAN NOT NULL DEFAULT TRUE,                    -- TRUE = grant, FALSE = explicit deny
    assigned_by   UUID REFERENCES users(id),
    assigned_at   TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_user_permission UNIQUE (user_id, permission_id)
);

COMMENT ON TABLE user_permissions IS 'Per-user permission overrides beyond what the assigned roles grant';

-- ============================================================================
-- TENANT MODULE ACCESS  (subscription-based module enablement)
-- ============================================================================
CREATE TABLE tenant_module_access (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    module_name     VARCHAR(100) NOT NULL,
    is_enabled      BOOLEAN NOT NULL DEFAULT FALSE,
    enabled_at      TIMESTAMPTZ,
    disabled_at     TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_tenant_module UNIQUE (tenant_id, module_name),
    CONSTRAINT chk_module_dates CHECK (
        disabled_at IS NULL 
        OR disabled_at > enabled_at
    )
);

COMMENT ON TABLE tenant_module_access IS
'Tracks which modules are enabled/disabled for each tenant based on subscription plan. Auto-synced when subscription changes.';

COMMENT ON COLUMN tenant_module_access.module_name IS
'Module identifier: students, attendance, finance, transport, hostel, online_classes, api_access, etc.';

COMMENT ON COLUMN tenant_module_access.is_enabled IS
'True if module is active in tenant subscription; False if not included in plan or disabled';

-- Index for fast lookup of enabled modules per tenant
CREATE INDEX idx_tenant_module_enabled 
ON tenant_module_access (tenant_id, module_name) 
WHERE is_enabled = TRUE;


-- ============================================================================
-- END file: 02_users_and_rbac.sql
-- ============================================================================


-- ============================================================================
-- END file: 02_users_and_rbac.sql
-- ============================================================================


-- ============================================================================
-- BEGIN file: 03_academic_structure.sql
-- ============================================================================

-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - ACADEMIC STRUCTURE
-- ============================================================================
-- File: 03_academic_structure.sql
-- Description: Academic years, grades, departments, classes, sections, subjects
-- ============================================================================

-- ============================================================================
-- ACADEMIC YEAR
-- ============================================================================
CREATE TABLE academic_years (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id   UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name        VARCHAR(50) NOT NULL,                               -- e.g. "2025-2026"
    start_date  DATE NOT NULL,
    end_date    DATE NOT NULL,
    is_current  BOOLEAN NOT NULL DEFAULT FALSE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT chk_academic_year_dates CHECK (end_date > start_date),
    CONSTRAINT uq_academic_year UNIQUE (tenant_id, name)
);

-- Partial unique index: only one current academic year per tenant
CREATE UNIQUE INDEX uq_current_academic_year
    ON academic_years (tenant_id) WHERE is_current = TRUE;

COMMENT ON TABLE academic_years IS 'Academic year definitions per tenant; exactly one may be marked is_current';

-- ============================================================================
-- GRADE / GRADE LEVEL
-- ============================================================================
CREATE TABLE grades (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id   UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name        VARCHAR(50) NOT NULL,                               -- Grade 1, Grade 2, ... Grade 12
    sequence    SMALLINT NOT NULL,                                  -- ordering
    description TEXT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_grade UNIQUE (tenant_id, name),
    CONSTRAINT uq_grade_sequence UNIQUE (tenant_id, sequence)
);

-- ============================================================================
-- DEPARTMENTS
-- ============================================================================
CREATE TABLE departments (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name            VARCHAR(150) NOT NULL,
    description     TEXT,
    head_teacher_id UUID REFERENCES users(id),                   -- department head
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_department UNIQUE (tenant_id, name)
);

-- ============================================================================
-- CLASSES  (linked to a grade and an academic year)
-- ============================================================================
CREATE TABLE classes (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    grade_id        UUID NOT NULL REFERENCES grades(id),
    academic_year_id UUID NOT NULL REFERENCES academic_years(id),
    name            VARCHAR(100) NOT NULL,                          -- e.g. "Grade 10 - 2025"
    section_count   SMALLINT NOT NULL DEFAULT 1 CHECK (section_count > 0),
    max_students    INTEGER,
    room_number     VARCHAR(20),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_class UNIQUE (tenant_id, grade_id, academic_year_id, name)
);

-- ============================================================================
-- SECTIONS  (subdivisions of a class: A, B, C ...)
-- ============================================================================
CREATE TABLE sections (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    class_id    UUID NOT NULL REFERENCES classes(id) ON DELETE CASCADE,
    name        VARCHAR(20) NOT NULL,                               -- A, B, C
    teacher_id  UUID REFERENCES users(id),                       -- class teacher
    max_students INTEGER,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_section UNIQUE (class_id, name)
);

COMMENT ON COLUMN sections.teacher_id IS 'The class teacher / homeroom teacher for this section';

-- ============================================================================
-- SUBJECTS
-- ============================================================================
CREATE TABLE subjects (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name            VARCHAR(150) NOT NULL,
    code            VARCHAR(20) NOT NULL,
    department_id   UUID REFERENCES departments(id),
    grade_id        UUID REFERENCES grades(id),                  -- NULL = available across grades
    is_elective     BOOLEAN NOT NULL DEFAULT FALSE,
    credits         NUMERIC(3,1),
    description     TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_subject_code UNIQUE (tenant_id, code)
);

-- ============================================================================
-- CLASS â†” SUBJECT MAPPING  (which teacher teaches which subject in which class)
-- ============================================================================
CREATE TABLE class_subjects (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    class_id    UUID NOT NULL REFERENCES classes(id) ON DELETE CASCADE,
    subject_id  UUID NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,
    teacher_id  UUID REFERENCES users(id),                       -- assigned teacher
    periods_per_week SMALLINT DEFAULT 1,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_class_subject UNIQUE (class_id, subject_id)
);


-- ============================================================================
-- END file: 03_academic_structure.sql
-- ============================================================================


-- ============================================================================
-- BEGIN file: 04_student_management.sql
-- ============================================================================

-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - STUDENT MANAGEMENT
-- ============================================================================
-- File: 04_student_management.sql
-- Description: Students, parents, documents, health records, promotions
-- ============================================================================

-- ============================================================================
-- PARENTS / GUARDIANS
-- ============================================================================
CREATE TABLE parents (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id         UUID REFERENCES users(id),                   -- linked user account (for parent portal)
    father_name     VARCHAR(150),
    mother_name     VARCHAR(150),
    guardian_name   VARCHAR(150),
    father_phone    VARCHAR(30),
    mother_phone    VARCHAR(30),
    guardian_phone  VARCHAR(30),
    father_email    VARCHAR(255),
    mother_email    VARCHAR(255),
    email           VARCHAR(255),                                   -- primary contact email
    father_occupation VARCHAR(100),
    mother_occupation VARCHAR(100),
    address         TEXT,
    city            VARCHAR(100),
    state           VARCHAR(100),
    pincode         VARCHAR(20),
    annual_income   NUMERIC(14,2),
    metadata        JSONB NOT NULL DEFAULT '{}',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at      TIMESTAMPTZ
);

COMMENT ON TABLE parents IS 'Parent / guardian records; linked to user accounts for portal access';

-- ============================================================================
-- STUDENTS
-- ============================================================================
CREATE TABLE students (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id             UUID REFERENCES users(id),               -- linked user account (for student portal)
    admission_number    VARCHAR(50) NOT NULL,
    roll_number         VARCHAR(30),
    first_name          VARCHAR(100) NOT NULL,
    last_name           VARCHAR(100),
    date_of_birth       DATE NOT NULL,
    gender              gender_type NOT NULL,
    blood_group         blood_group_type DEFAULT 'unknown',
    religion            VARCHAR(50),
    caste               VARCHAR(50),
    nationality         VARCHAR(50) DEFAULT 'Indian',
    mother_tongue       VARCHAR(50),
    aadhaar_number      VARCHAR(12),                                -- encrypted at app layer
    admission_date      DATE NOT NULL,
    class_id            UUID NOT NULL REFERENCES classes(id),
    section_id          UUID REFERENCES sections(id),
    parent_id           UUID REFERENCES parents(id),
    previous_school     VARCHAR(255),
    address             TEXT,
    photo_url           TEXT,
    is_active           BOOLEAN NOT NULL DEFAULT TRUE,
    status              VARCHAR(20) NOT NULL DEFAULT 'active'
                        CHECK (status IN ('active', 'inactive', 'transferred', 'graduated', 'expelled')),
    metadata            JSONB NOT NULL DEFAULT '{}',
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at          TIMESTAMPTZ,

    CONSTRAINT uq_admission_number UNIQUE (tenant_id, admission_number)
);

COMMENT ON TABLE students IS 'Core student records; one row per enrolled student per tenant';

-- ============================================================================
-- STUDENT DOCUMENTS
-- ============================================================================
CREATE TABLE student_documents (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    student_id      UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    document_type   document_type NOT NULL,
    document_name   VARCHAR(255),
    document_url    TEXT NOT NULL,
    file_size_bytes BIGINT,
    mime_type       VARCHAR(100),
    uploaded_by     UUID REFERENCES users(id),
    uploaded_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    verified        BOOLEAN NOT NULL DEFAULT FALSE,
    verified_by     UUID REFERENCES users(id),
    verified_at     TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- STUDENT HEALTH RECORDS
-- ============================================================================
CREATE TABLE student_health_records (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    student_id          UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    height_cm           NUMERIC(5,2),
    weight_kg           NUMERIC(5,2),
    bmi                 NUMERIC(5,2),
    blood_pressure      VARCHAR(20),
    vision_left         VARCHAR(20),
    vision_right        VARCHAR(20),
    allergies           TEXT,
    medical_conditions  TEXT,
    medications         TEXT,
    emergency_contact_name  VARCHAR(150),
    emergency_contact_phone VARCHAR(30),
    emergency_contact_relation VARCHAR(50),
    insurance_provider  VARCHAR(150),
    insurance_number    VARCHAR(100),
    last_checkup_date   DATE,
    doctor_name         VARCHAR(150),
    remarks             TEXT,
    recorded_by         UUID REFERENCES users(id),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE student_health_records IS 'Periodic health check data for students';

-- ============================================================================
-- STUDENT PROMOTIONS
-- ============================================================================
CREATE TABLE student_promotions (
    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    student_id              UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    from_class_id           UUID NOT NULL REFERENCES classes(id),
    to_class_id             UUID NOT NULL REFERENCES classes(id),
    from_section_id         UUID REFERENCES sections(id),
    to_section_id           UUID REFERENCES sections(id),
    from_academic_year_id   UUID NOT NULL REFERENCES academic_years(id),
    to_academic_year_id     UUID NOT NULL REFERENCES academic_years(id),
    promotion_date          DATE NOT NULL,
    status                  VARCHAR(20) NOT NULL DEFAULT 'promoted'
                            CHECK (status IN ('promoted', 'retained', 'conditional')),
    remarks                 TEXT,
    promoted_by             UUID REFERENCES users(id),
    created_at              TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE student_promotions IS 'Tracks year-over-year class promotions and retentions';


-- ============================================================================
-- END file: 04_student_management.sql
-- ============================================================================


-- ============================================================================
-- BEGIN file: 05_attendance.sql
-- ============================================================================

-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - ATTENDANCE MANAGEMENT
-- ============================================================================
-- File: 05_attendance.sql
-- Description: Student/teacher attendance, biometric, leave requests
-- ============================================================================

-- ============================================================================
-- STUDENT ATTENDANCE
-- ============================================================================
CREATE TABLE student_attendance (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    student_id      UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    class_id        UUID NOT NULL REFERENCES classes(id),
    section_id      UUID REFERENCES sections(id),
    date            DATE NOT NULL,
    status          attendance_status NOT NULL,
    check_in_time   TIME,
    check_out_time  TIME,
    remarks         TEXT,
    marked_by       UUID REFERENCES users(id),
    marked_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    source          VARCHAR(20) DEFAULT 'manual'
                    CHECK (source IN ('manual', 'biometric', 'app', 'import')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_student_attendance UNIQUE (student_id, date)
);

COMMENT ON TABLE student_attendance IS 'Daily attendance records for students; one row per student per date';

-- ============================================================================
-- TEACHER / STAFF ATTENDANCE
-- ============================================================================
CREATE TABLE teacher_attendance (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    teacher_id      UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    date            DATE NOT NULL,
    status          attendance_status NOT NULL,
    check_in_time   TIME,
    check_out_time  TIME,
    work_hours      NUMERIC(4,2),
    remarks         TEXT,
    marked_by       UUID REFERENCES users(id),
    source          VARCHAR(20) DEFAULT 'manual'
                    CHECK (source IN ('manual', 'biometric', 'app', 'import')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_teacher_attendance UNIQUE (teacher_id, date)
);

-- ============================================================================
-- BIOMETRIC DEVICES
-- ============================================================================
CREATE TABLE biometric_devices (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    device_name     VARCHAR(100) NOT NULL,
    device_serial   VARCHAR(100) NOT NULL,
    location        VARCHAR(255),
    ip_address      INET,
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    last_sync_at    TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_biometric_device UNIQUE (tenant_id, device_serial)
);

-- ============================================================================
-- BIOMETRIC ATTENDANCE LOGS
-- ============================================================================
CREATE TABLE biometric_attendance (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id             UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    biometric_device_id UUID REFERENCES biometric_devices(id),
    scan_time           TIMESTAMPTZ NOT NULL,
    verification_mode   verification_mode NOT NULL DEFAULT 'fingerprint',
    direction           VARCHAR(10) CHECK (direction IN ('in', 'out')),
    status              attendance_status,
    raw_data            JSONB,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE biometric_attendance IS 'Raw biometric scan events; processed into student/teacher attendance';

-- ============================================================================
-- LEAVE REQUESTS  (for both teachers/staff and students)
-- ============================================================================
CREATE TABLE leave_requests (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    leave_type      leave_type NOT NULL,
    from_date       DATE NOT NULL,
    to_date         DATE NOT NULL,
    total_days      NUMERIC(4,1) NOT NULL,
    reason          TEXT NOT NULL,
    attachment_url  TEXT,
    status          leave_status NOT NULL DEFAULT 'pending',
    approved_by     UUID REFERENCES users(id),
    approved_at     TIMESTAMPTZ,
    rejection_reason TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT chk_leave_dates CHECK (to_date >= from_date),
    CONSTRAINT chk_total_days CHECK (total_days > 0)
);

-- ============================================================================
-- LEAVE BALANCES  (annual leave quotas per user)
-- ============================================================================
CREATE TABLE leave_balances (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    academic_year_id UUID NOT NULL REFERENCES academic_years(id),
    leave_type      leave_type NOT NULL,
    total_allowed   NUMERIC(4,1) NOT NULL DEFAULT 0,
    used            NUMERIC(4,1) NOT NULL DEFAULT 0,
    remaining       NUMERIC(4,1) GENERATED ALWAYS AS (total_allowed - used) STORED,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_leave_balance UNIQUE (user_id, academic_year_id, leave_type),
    CONSTRAINT chk_used_within_limit CHECK (used <= total_allowed)
);


-- ============================================================================
-- END file: 05_attendance.sql
-- ============================================================================


-- ============================================================================
-- BEGIN file: 06_examination_and_grading.sql
-- ============================================================================

-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - EXAMINATION & GRADING
-- ============================================================================
-- File: 06_examination_and_grading.sql
-- Description: Exams, timetables, grade systems, marks, results, report cards
-- ============================================================================

-- ============================================================================
-- GRADE SYSTEM  (grading scale definitions)
-- ============================================================================
CREATE TABLE grade_systems (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name            VARCHAR(50) NOT NULL,                           -- e.g. "CBSE Grading", "ICSE Grading"
    is_default      BOOLEAN NOT NULL DEFAULT FALSE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_grade_system UNIQUE (tenant_id, name)
);

-- Partial unique index: one default grade system per tenant
CREATE UNIQUE INDEX uq_default_grade_system
    ON grade_systems (tenant_id) WHERE is_default = TRUE;

-- ============================================================================
-- GRADE SCALE ENTRIES  (rows within a grade system)
-- ============================================================================
CREATE TABLE grade_scale_entries (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    grade_system_id UUID NOT NULL REFERENCES grade_systems(id) ON DELETE CASCADE,
    grade_name      VARCHAR(10) NOT NULL,                           -- A+, A, B+, B, etc.
    min_percentage  NUMERIC(5,2) NOT NULL,
    max_percentage  NUMERIC(5,2) NOT NULL,
    grade_point     NUMERIC(4,2),
    description     VARCHAR(100),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT chk_percentage_range CHECK (max_percentage >= min_percentage AND min_percentage >= 0 AND max_percentage <= 100),
    CONSTRAINT uq_grade_entry UNIQUE (grade_system_id, grade_name)
);

-- ============================================================================
-- EXAMS
-- ============================================================================
CREATE TABLE exams (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    academic_year_id UUID NOT NULL REFERENCES academic_years(id),
    name            VARCHAR(150) NOT NULL,
    exam_type       exam_type NOT NULL,
    start_date      DATE,
    end_date        DATE,
    grade_system_id UUID REFERENCES grade_systems(id),
    description     TEXT,
    is_published    BOOLEAN NOT NULL DEFAULT FALSE,
    created_by      UUID REFERENCES users(id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT chk_exam_dates CHECK (end_date IS NULL OR end_date >= start_date),
    CONSTRAINT uq_exam UNIQUE (tenant_id, academic_year_id, name)
);

-- ============================================================================
-- EXAM TIMETABLE
-- ============================================================================
CREATE TABLE exam_timetables (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    exam_id     UUID NOT NULL REFERENCES exams(id) ON DELETE CASCADE,
    class_id    UUID NOT NULL REFERENCES classes(id),
    subject_id  UUID NOT NULL REFERENCES subjects(id),
    exam_date   DATE NOT NULL,
    start_time  TIME NOT NULL,
    end_time    TIME NOT NULL,
    room_number VARCHAR(20),
    max_marks   NUMERIC(6,2) NOT NULL DEFAULT 100,
    passing_marks NUMERIC(6,2),
    instructions TEXT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT chk_exam_time CHECK (end_time > start_time),
    CONSTRAINT uq_exam_timetable UNIQUE (exam_id, class_id, subject_id)
);

-- ============================================================================
-- MARKS ENTRY  (per student per exam per subject)
-- ============================================================================
CREATE TABLE marks_entries (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    student_id      UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    exam_id         UUID NOT NULL REFERENCES exams(id) ON DELETE CASCADE,
    subject_id      UUID NOT NULL REFERENCES subjects(id),
    class_id        UUID NOT NULL REFERENCES classes(id),
    obtained_marks  NUMERIC(6,2),
    total_marks     NUMERIC(6,2) NOT NULL,
    percentage      NUMERIC(5,2) GENERATED ALWAYS AS (
                        CASE WHEN total_marks > 0 THEN (obtained_marks / total_marks) * 100 ELSE 0 END
                    ) STORED,
    grade_entry_id  UUID REFERENCES grade_scale_entries(id),
    is_absent       BOOLEAN NOT NULL DEFAULT FALSE,
    remarks         TEXT,
    entered_by      UUID REFERENCES users(id),
    entered_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    verified_by     UUID REFERENCES users(id),
    verified_at     TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT chk_marks CHECK (obtained_marks IS NULL OR (obtained_marks >= 0 AND obtained_marks <= total_marks)),
    CONSTRAINT uq_marks_entry UNIQUE (student_id, exam_id, subject_id)
);

COMMENT ON TABLE marks_entries IS 'Individual subject marks per student per exam; percentage is auto-computed';

-- ============================================================================
-- RESULTS  (aggregated per student per exam)
-- ============================================================================
CREATE TABLE results (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    student_id      UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    exam_id         UUID NOT NULL REFERENCES exams(id) ON DELETE CASCADE,
    class_id        UUID NOT NULL REFERENCES classes(id),
    total_obtained  NUMERIC(8,2),
    total_max       NUMERIC(8,2),
    percentage      NUMERIC(5,2),
    grade_entry_id  UUID REFERENCES grade_scale_entries(id),
    gpa             NUMERIC(4,2),
    rank            INTEGER,
    status          VARCHAR(20) DEFAULT 'pass' CHECK (status IN ('pass', 'fail', 'compartment', 'withheld')),
    remarks         TEXT,
    is_published    BOOLEAN NOT NULL DEFAULT FALSE,
    published_at    TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_result UNIQUE (student_id, exam_id)
);

-- ============================================================================
-- REPORT CARD TEMPLATES
-- ============================================================================
CREATE TABLE report_card_templates (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    template_name   VARCHAR(150) NOT NULL,
    layout          JSONB NOT NULL DEFAULT '{}',                    -- template structure/config
    header_html     TEXT,
    footer_html     TEXT,
    is_default      BOOLEAN NOT NULL DEFAULT FALSE,
    created_by      UUID REFERENCES users(id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Partial unique: one default template per tenant
CREATE UNIQUE INDEX uq_default_report_card_template
    ON report_card_templates (tenant_id) WHERE is_default = TRUE;


-- ============================================================================
-- END file: 06_examination_and_grading.sql
-- ============================================================================


-- ============================================================================
-- BEGIN file: 07_finance.sql
-- ============================================================================

-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - FINANCE & FEE MANAGEMENT
-- ============================================================================
-- File: 07_finance.sql
-- Description: Fee structures, collection, online payments, scholarships, alerts
-- ============================================================================

-- ============================================================================
-- FEE STRUCTURES
-- ============================================================================
CREATE TABLE fee_structures (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    academic_year_id UUID NOT NULL REFERENCES academic_years(id),
    class_id        UUID REFERENCES classes(id),                 -- NULL = applies to all classes
    fee_type        fee_type NOT NULL,
    name            VARCHAR(150) NOT NULL,
    amount          NUMERIC(12,2) NOT NULL CHECK (amount >= 0),
    frequency       fee_frequency NOT NULL DEFAULT 'monthly',
    due_day         SMALLINT CHECK (due_day BETWEEN 1 AND 28),      -- day of month for recurring
    due_date        DATE,                                           -- for one-time fees
    late_fee_per_day NUMERIC(8,2) DEFAULT 0,
    is_mandatory    BOOLEAN NOT NULL DEFAULT TRUE,
    description     TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_fee_structure UNIQUE (tenant_id, academic_year_id, class_id, fee_type, name)
);

COMMENT ON TABLE fee_structures IS 'Fee schedule definitions per class per academic year';

-- ============================================================================
-- FEE INVOICES  (generated per student per fee period)
-- ============================================================================
CREATE TABLE fee_invoices (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    student_id          UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    fee_structure_id    UUID NOT NULL REFERENCES fee_structures(id),
    invoice_number      VARCHAR(50) NOT NULL,
    period_label        VARCHAR(50),                                -- e.g. "Jan 2026", "Q1 2025-26"
    amount              NUMERIC(12,2) NOT NULL CHECK (amount >= 0),
    discount_amount     NUMERIC(12,2) NOT NULL DEFAULT 0,
    scholarship_amount  NUMERIC(12,2) NOT NULL DEFAULT 0,
    late_fee            NUMERIC(12,2) NOT NULL DEFAULT 0,
    net_amount          NUMERIC(12,2) GENERATED ALWAYS AS (
                            amount - discount_amount - scholarship_amount + late_fee
                        ) STORED,
    due_date            DATE NOT NULL,
    status              payment_status NOT NULL DEFAULT 'pending',
    metadata            JSONB NOT NULL DEFAULT '{}',
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_invoice_number UNIQUE (tenant_id, invoice_number)
);

COMMENT ON TABLE fee_invoices IS 'Individual fee invoices generated per student; tracks discounts and late fees';

-- ============================================================================
-- FEE COLLECTIONS  (payments against invoices)
-- ============================================================================
CREATE TABLE fee_collections (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    student_id          UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    fee_invoice_id      UUID REFERENCES fee_invoices(id),
    fee_structure_id    UUID NOT NULL REFERENCES fee_structures(id),
    receipt_number      VARCHAR(50) NOT NULL,
    amount_paid         NUMERIC(12,2) NOT NULL CHECK (amount_paid > 0),
    payment_date        DATE NOT NULL,
    payment_mode        payment_mode NOT NULL,
    transaction_id      VARCHAR(100),
    bank_name           VARCHAR(100),
    cheque_number       VARCHAR(50),
    receipt_url         TEXT,
    remarks             TEXT,
    collected_by        UUID REFERENCES users(id),
    cancelled           BOOLEAN NOT NULL DEFAULT FALSE,
    cancelled_at        TIMESTAMPTZ,
    cancelled_by        UUID REFERENCES users(id),
    cancellation_reason TEXT,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_receipt_number UNIQUE (tenant_id, receipt_number)
);

-- ============================================================================
-- ONLINE PAYMENTS  (gateway integration records)
-- ============================================================================
CREATE TABLE online_payments (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    fee_collection_id   UUID REFERENCES fee_collections(id),
    fee_invoice_id      UUID REFERENCES fee_invoices(id),
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    gateway_name        VARCHAR(50) NOT NULL,                       -- razorpay, stripe, paytm, ccavenue
    gateway_order_id    VARCHAR(255),
    gateway_payment_id  VARCHAR(255),
    gateway_signature   VARCHAR(255),
    amount              NUMERIC(12,2) NOT NULL,
    currency            VARCHAR(3) NOT NULL DEFAULT 'INR',
    gateway_status      VARCHAR(50),                                -- created, authorized, captured, failed, refunded
    gateway_response    JSONB,
    webhook_payload     JSONB,
    webhook_verified    BOOLEAN DEFAULT FALSE,
    refund_id           VARCHAR(255),
    refund_amount       NUMERIC(12,2),
    refund_status       VARCHAR(50),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE online_payments IS 'Payment gateway transaction records with full webhook audit trail';

-- ============================================================================
-- SCHOLARSHIPS
-- ============================================================================
CREATE TABLE scholarships (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    student_id          UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    scholarship_name    VARCHAR(200) NOT NULL,
    scholarship_type    VARCHAR(50) CHECK (scholarship_type IN ('merit', 'need_based', 'sports', 'government', 'other')),
    percentage_discount NUMERIC(5,2) CHECK (percentage_discount BETWEEN 0 AND 100),
    amount_discount     NUMERIC(12,2) CHECK (amount_discount >= 0),
    valid_from          DATE NOT NULL,
    valid_to            DATE NOT NULL,
    fee_types_applicable JSONB,                                     -- ["tuition","hostel"] or null = all
    status              approval_status NOT NULL DEFAULT 'pending',
    approved_by         UUID REFERENCES users(id),
    approved_at         TIMESTAMPTZ,
    remarks             TEXT,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT chk_scholarship_dates CHECK (valid_to >= valid_from),
    CONSTRAINT chk_scholarship_discount CHECK (
        percentage_discount IS NOT NULL OR amount_discount IS NOT NULL
    )
);

-- ============================================================================
-- FEE DUE ALERTS
-- ============================================================================
CREATE TABLE fee_due_alerts (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    student_id      UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    fee_invoice_id  UUID REFERENCES fee_invoices(id),
    due_amount      NUMERIC(12,2) NOT NULL,
    due_date        DATE NOT NULL,
    alert_type      alert_type NOT NULL,
    alert_sent_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    message_content TEXT,
    delivery_status notification_status DEFAULT 'queued',
    error_message   TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- EXPENSE CATEGORIES & TRACKING  (school expenses)
-- ============================================================================
CREATE TABLE expense_categories (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id   UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name        VARCHAR(100) NOT NULL,
    parent_id   UUID REFERENCES expense_categories(id),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_expense_category UNIQUE (tenant_id, name)
);

CREATE TABLE expenses (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    category_id     UUID NOT NULL REFERENCES expense_categories(id),
    amount          NUMERIC(14,2) NOT NULL CHECK (amount > 0),
    description     TEXT NOT NULL,
    expense_date    DATE NOT NULL,
    payment_mode    payment_mode,
    receipt_url     TEXT,
    approved_by     UUID REFERENCES users(id),
    status          approval_status NOT NULL DEFAULT 'pending',
    created_by      UUID NOT NULL REFERENCES users(id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ============================================================================
-- END file: 07_finance.sql
-- ============================================================================


-- ============================================================================
-- BEGIN file: 08_communication.sql
-- ============================================================================

-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - COMMUNICATION
-- ============================================================================
-- File: 08_communication.sql
-- Description: Announcements, messaging, notifications, logs
-- ============================================================================

-- ============================================================================
-- ANNOUNCEMENTS  (broadcast to roles / classes)
-- ============================================================================
CREATE TABLE announcements (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    title           VARCHAR(255) NOT NULL,
    content         TEXT NOT NULL,
    content_html    TEXT,
    target_roles    JSONB,                                          -- ["student","teacher","parent"]
    target_class_ids JSONB,                                         -- ["id1","id2","id3"] or null = all
    target_section_ids JSONB,
    priority        priority_level NOT NULL DEFAULT 'medium',
    attachment_urls JSONB,                                          -- ["https://...","https://..."]
    is_published    BOOLEAN NOT NULL DEFAULT FALSE,
    published_at    TIMESTAMPTZ,
    expires_at      TIMESTAMPTZ,
    sent_by         UUID NOT NULL REFERENCES users(id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at      TIMESTAMPTZ
);

COMMENT ON TABLE announcements IS 'School-wide or targeted announcements; can target specific roles and classes';

-- ============================================================================
-- ANNOUNCEMENT READ TRACKING
-- ============================================================================
CREATE TABLE announcement_reads (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    announcement_id UUID NOT NULL REFERENCES announcements(id) ON DELETE CASCADE,
    user_id         UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    read_at         TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_announcement_read UNIQUE (announcement_id, user_id)
);

-- ============================================================================
-- MESSAGES  (1-to-1 or threaded messaging)
-- ============================================================================
CREATE TABLE messages (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    from_user_id        UUID NOT NULL REFERENCES users(id),
    to_user_id          UUID NOT NULL REFERENCES users(id),
    subject             VARCHAR(255),
    message_body        TEXT NOT NULL,
    parent_message_id   UUID REFERENCES messages(id),            -- threading
    is_read             BOOLEAN NOT NULL DEFAULT FALSE,
    read_at             TIMESTAMPTZ,
    attachment_urls     JSONB,
    is_archived         BOOLEAN NOT NULL DEFAULT FALSE,
    sent_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at          TIMESTAMPTZ
);

COMMENT ON COLUMN messages.parent_message_id IS 'References the original message for threaded conversations';

-- ============================================================================
-- NOTIFICATIONS  (in-app, push, SMS, email)
-- ============================================================================
CREATE TABLE notifications (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id   UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    title       VARCHAR(255) NOT NULL,
    body        TEXT,
    type        VARCHAR(50),                                        -- fee_due, attendance, exam_result, etc.
    channel     notification_channel NOT NULL DEFAULT 'in_app',
    reference_type VARCHAR(50),                                     -- "student", "fee_invoice", etc.
    reference_id   UUID,                                         -- FK to the referenced entity
    action_url  TEXT,
    is_read     BOOLEAN NOT NULL DEFAULT FALSE,
    read_at     TIMESTAMPTZ,
    sent_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- NOTIFICATION DELIVERY LOG
-- ============================================================================
CREATE TABLE notification_logs (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    notification_id UUID REFERENCES notifications(id) ON DELETE SET NULL,
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    recipient       VARCHAR(255),                                   -- phone/email/device_token
    sent_via        notification_channel NOT NULL,
    provider        VARCHAR(50),                                    -- twilio, sendgrid, firebase, etc.
    provider_message_id VARCHAR(255),
    status          notification_status NOT NULL DEFAULT 'queued',
    error_message   TEXT,
    cost            NUMERIC(8,4),                                   -- SMS cost tracking
    payload         JSONB,
    sent_at         TIMESTAMPTZ,
    delivered_at    TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE notification_logs IS 'Delivery audit trail for all outbound notifications (SMS, email, push)';

-- ============================================================================
-- SMS / EMAIL TEMPLATES
-- ============================================================================
CREATE TABLE message_templates (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id   UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name        VARCHAR(100) NOT NULL,
    channel     notification_channel NOT NULL,
    subject     VARCHAR(255),
    body        TEXT NOT NULL,                                       -- supports {{variable}} placeholders
    variables   JSONB,                                              -- ["student_name","class","due_amount"]
    is_active   BOOLEAN NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_message_template UNIQUE (tenant_id, name, channel)
);


-- ============================================================================
-- END file: 08_communication.sql
-- ============================================================================


-- ============================================================================
-- BEGIN file: 09_transport.sql
-- ============================================================================

-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - TRANSPORT MANAGEMENT
-- ============================================================================
-- File: 09_transport.sql
-- Description: Routes, vehicles, drivers, student allocations, transport fees
-- ============================================================================

-- ============================================================================
-- DRIVERS
-- ============================================================================
CREATE TABLE drivers (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id         UUID REFERENCES users(id),
    name            VARCHAR(150) NOT NULL,
    license_number  VARCHAR(50) NOT NULL,
    license_expiry  DATE,
    phone           VARCHAR(30) NOT NULL,
    alternate_phone VARCHAR(30),
    address         TEXT,
    date_of_birth   DATE,
    blood_group     blood_group_type,
    photo_url       TEXT,
    hire_date       DATE NOT NULL,
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_driver_license UNIQUE (tenant_id, license_number)
);

-- ============================================================================
-- TRANSPORT ROUTES
-- ============================================================================
CREATE TABLE transport_routes (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id   UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    route_name  VARCHAR(150) NOT NULL,
    route_code  VARCHAR(20),
    start_point VARCHAR(255) NOT NULL,
    end_point   VARCHAR(255) NOT NULL,
    distance_km NUMERIC(6,2),
    estimated_time_min INTEGER,
    stops       JSONB NOT NULL DEFAULT '[]',                        -- [{name, lat, lng, sequence, pickup_time}]
    is_active   BOOLEAN NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_route UNIQUE (tenant_id, route_name)
);

-- ============================================================================
-- VEHICLES
-- ============================================================================
CREATE TABLE vehicles (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    vehicle_number  VARCHAR(30) NOT NULL,
    vehicle_type    VARCHAR(50),                                    -- bus, van, auto
    make            VARCHAR(50),
    model           VARCHAR(50),
    year            SMALLINT,
    capacity        SMALLINT NOT NULL CHECK (capacity > 0),
    driver_id       UUID REFERENCES drivers(id),
    route_id        UUID REFERENCES transport_routes(id),
    insurance_number VARCHAR(100),
    insurance_expiry DATE,
    fitness_expiry  DATE,
    gps_device_id   VARCHAR(100),
    status          vehicle_status NOT NULL DEFAULT 'active',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_vehicle UNIQUE (tenant_id, vehicle_number)
);

-- ============================================================================
-- STUDENT ROUTE ALLOCATION
-- ============================================================================
CREATE TABLE student_route_allocations (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    student_id          UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    route_id            UUID NOT NULL REFERENCES transport_routes(id),
    vehicle_id          UUID REFERENCES vehicles(id),
    pickup_stop         VARCHAR(255),
    dropoff_stop        VARCHAR(255),
    pickup_time         TIME,
    dropoff_time        TIME,
    transport_fee_monthly NUMERIC(10,2) CHECK (transport_fee_monthly >= 0),
    is_active           BOOLEAN NOT NULL DEFAULT TRUE,
    effective_from      DATE NOT NULL,
    effective_to        DATE,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- TRANSPORT FEES  (monthly tracking)
-- ============================================================================
CREATE TABLE transport_fees (
    id                          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    student_route_allocation_id UUID NOT NULL REFERENCES student_route_allocations(id) ON DELETE CASCADE,
    tenant_id                   UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    month                       SMALLINT NOT NULL CHECK (month BETWEEN 1 AND 12),
    year                        SMALLINT NOT NULL,
    amount                      NUMERIC(10,2) NOT NULL CHECK (amount >= 0),
    paid_status                 payment_status NOT NULL DEFAULT 'pending',
    payment_date                DATE,
    payment_mode                payment_mode,
    receipt_number              VARCHAR(50),
    created_at                  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at                  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_transport_fee UNIQUE (student_route_allocation_id, month, year)
);

-- ============================================================================
-- VEHICLE MAINTENANCE LOG
-- ============================================================================
CREATE TABLE vehicle_maintenance_logs (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    vehicle_id      UUID NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    maintenance_date DATE NOT NULL,
    description     TEXT NOT NULL,
    cost            NUMERIC(10,2),
    next_maintenance_date DATE,
    performed_by    VARCHAR(150),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- GPS TRACKING LOG  (for live tracking integration)
-- ============================================================================
CREATE TABLE gps_tracking_logs (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    vehicle_id  UUID NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,
    latitude    NUMERIC(10,7) NOT NULL,
    longitude   NUMERIC(10,7) NOT NULL,
    speed_kmh   NUMERIC(5,1),
    heading     SMALLINT,
    recorded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE gps_tracking_logs IS 'Real-time GPS data from vehicle tracking devices; high-volume, consider partitioning';


-- ============================================================================
-- END file: 09_transport.sql
-- ============================================================================


-- ============================================================================
-- BEGIN file: 10_library.sql
-- ============================================================================

-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - LIBRARY MANAGEMENT
-- ============================================================================
-- File: 10_library.sql
-- Description: Catalog, book issues, returns, fines
-- ============================================================================

-- ============================================================================
-- LIBRARY CATALOG
-- ============================================================================
CREATE TABLE library_catalog (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    book_title          VARCHAR(255) NOT NULL,
    author              VARCHAR(255),
    isbn                VARCHAR(20),
    publisher           VARCHAR(200),
    edition             VARCHAR(50),
    publication_year    SMALLINT,
    language            VARCHAR(50) DEFAULT 'English',
    category            VARCHAR(100),                               -- Fiction, Science, Reference, etc.
    total_copies        INTEGER NOT NULL DEFAULT 1 CHECK (total_copies > 0),
    available_copies    INTEGER NOT NULL DEFAULT 1 CHECK (available_copies >= 0),
    rack_number         VARCHAR(20),
    shelf_number        VARCHAR(20),
    book_image_url      TEXT,
    barcode             VARCHAR(50),
    description         TEXT,
    tags                JSONB,                                      -- ["physics","class10","reference"]
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT chk_available_copies CHECK (available_copies <= total_copies)
);

CREATE INDEX idx_library_isbn ON library_catalog (tenant_id, isbn) WHERE isbn IS NOT NULL;

-- ============================================================================
-- BOOK ISSUES
-- ============================================================================
CREATE TABLE book_issues (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    book_id         UUID NOT NULL REFERENCES library_catalog(id),
    student_id      UUID REFERENCES students(id),                -- NULL if issued to staff
    user_id         UUID REFERENCES users(id),                   -- staff member
    issue_date      DATE NOT NULL,
    due_date        DATE NOT NULL,
    return_date     DATE,
    renewal_count   SMALLINT NOT NULL DEFAULT 0,
    max_renewals    SMALLINT NOT NULL DEFAULT 2,
    fine_amount     NUMERIC(8,2) NOT NULL DEFAULT 0,
    status          book_issue_status NOT NULL DEFAULT 'issued',
    remarks         TEXT,
    issued_by       UUID REFERENCES users(id),
    returned_to     UUID REFERENCES users(id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT chk_due_date CHECK (due_date >= issue_date),
    CONSTRAINT chk_return_date CHECK (return_date IS NULL OR return_date >= issue_date),
    CONSTRAINT chk_borrower CHECK (student_id IS NOT NULL OR user_id IS NOT NULL)
);

-- ============================================================================
-- LIBRARY FINES
-- ============================================================================
CREATE TABLE library_fines (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    book_issue_id   UUID NOT NULL REFERENCES book_issues(id) ON DELETE CASCADE,
    fine_per_day    NUMERIC(6,2) NOT NULL CHECK (fine_per_day >= 0),
    overdue_days    INTEGER NOT NULL DEFAULT 0,
    total_fine      NUMERIC(8,2) NOT NULL DEFAULT 0,
    paid_status     payment_status NOT NULL DEFAULT 'pending',
    paid_amount     NUMERIC(8,2) DEFAULT 0,
    payment_date    DATE,
    payment_mode    payment_mode,
    waived          BOOLEAN NOT NULL DEFAULT FALSE,
    waived_by       UUID REFERENCES users(id),
    waiver_reason   TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- LIBRARY SETTINGS  (per tenant)
-- ============================================================================
CREATE TABLE library_settings (
    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id               UUID NOT NULL UNIQUE REFERENCES tenants(id) ON DELETE CASCADE,
    max_books_per_student   SMALLINT NOT NULL DEFAULT 3,
    max_books_per_staff     SMALLINT NOT NULL DEFAULT 5,
    loan_period_days        SMALLINT NOT NULL DEFAULT 14,
    fine_per_day            NUMERIC(6,2) NOT NULL DEFAULT 1.00,
    max_renewals            SMALLINT NOT NULL DEFAULT 2,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ============================================================================
-- END file: 10_library.sql
-- ============================================================================


-- ============================================================================
-- BEGIN file: 11_hr_and_staff.sql
-- ============================================================================

-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - HR & STAFF MANAGEMENT
-- ============================================================================
-- File: 11_hr_and_staff.sql
-- Description: Staff records, payroll, performance evaluations
-- ============================================================================

-- ============================================================================
-- STAFF  (employees other than or in addition to the user record)
-- ============================================================================
CREATE TABLE staff (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id         UUID REFERENCES users(id),                   -- linked login account
    employee_id     VARCHAR(50) NOT NULL,
    first_name      VARCHAR(100) NOT NULL,
    last_name       VARCHAR(100),
    designation     VARCHAR(100) NOT NULL,                          -- Principal, Teacher, Clerk, etc.
    department_id   UUID REFERENCES departments(id),
    date_of_birth   DATE,
    gender          gender_type,
    qualification   VARCHAR(200),
    specialization  VARCHAR(200),
    experience_years NUMERIC(4,1),
    joining_date    DATE NOT NULL,
    confirmation_date DATE,
    resignation_date DATE,
    last_working_date DATE,
    employment_type VARCHAR(30) DEFAULT 'full_time'
                    CHECK (employment_type IN ('full_time', 'part_time', 'contract', 'temporary')),
    basic_salary    NUMERIC(12,2) CHECK (basic_salary >= 0),
    bank_name       VARCHAR(100),
    bank_account    VARCHAR(30),
    bank_ifsc       VARCHAR(20),
    pan_number      VARCHAR(10),
    uan_number      VARCHAR(20),                                    -- Universal Account Number (PF)
    address         TEXT,
    phone           VARCHAR(30),
    emergency_contact_name VARCHAR(150),
    emergency_contact_phone VARCHAR(30),
    photo_url       TEXT,
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    metadata        JSONB NOT NULL DEFAULT '{}',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at      TIMESTAMPTZ,

    CONSTRAINT uq_employee_id UNIQUE (tenant_id, employee_id)
);

COMMENT ON TABLE staff IS 'HR records for all school employees; linked to users table for authentication';

-- ============================================================================
-- SALARY COMPONENTS  (configurable allowances/deductions)
-- ============================================================================
CREATE TABLE salary_components (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id   UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name        VARCHAR(100) NOT NULL,                              -- HRA, DA, PF, Professional Tax, etc.
    type        VARCHAR(20) NOT NULL CHECK (type IN ('earning', 'deduction')),
    is_taxable  BOOLEAN NOT NULL DEFAULT TRUE,
    is_fixed    BOOLEAN NOT NULL DEFAULT TRUE,                      -- fixed vs percentage-based
    percentage_of VARCHAR(50),                                      -- "basic_salary" if percentage-based
    is_active   BOOLEAN NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_salary_component UNIQUE (tenant_id, name)
);

-- ============================================================================
-- PAYROLL
-- ============================================================================
CREATE TABLE payroll (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    staff_id        UUID NOT NULL REFERENCES staff(id) ON DELETE CASCADE,
    month           SMALLINT NOT NULL CHECK (month BETWEEN 1 AND 12),
    year            SMALLINT NOT NULL,
    working_days    SMALLINT,
    present_days    SMALLINT,
    basic_salary    NUMERIC(12,2) NOT NULL,
    earnings        JSONB NOT NULL DEFAULT '{}',                    -- {"hra": 5000, "da": 3000, ...}
    deductions      JSONB NOT NULL DEFAULT '{}',                    -- {"pf": 1800, "tax": 2000, ...}
    gross_salary    NUMERIC(12,2) NOT NULL,
    total_deductions NUMERIC(12,2) NOT NULL DEFAULT 0,
    net_salary      NUMERIC(12,2) NOT NULL,
    payment_date    DATE,
    payment_mode    payment_mode,
    transaction_ref VARCHAR(100),
    status          payroll_status NOT NULL DEFAULT 'draft',
    generated_by    UUID REFERENCES users(id),
    approved_by     UUID REFERENCES users(id),
    remarks         TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_payroll UNIQUE (staff_id, month, year),
    CONSTRAINT chk_salary CHECK (net_salary >= 0)
);

-- ============================================================================
-- PERFORMANCE EVALUATIONS
-- ============================================================================
CREATE TABLE performance_evaluations (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    staff_id        UUID NOT NULL REFERENCES staff(id) ON DELETE CASCADE,
    academic_year_id UUID REFERENCES academic_years(id),
    evaluation_date DATE NOT NULL,
    evaluator_id    UUID NOT NULL REFERENCES users(id),
    rating          SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5),
    categories      JSONB NOT NULL DEFAULT '{}',                    -- {"teaching": 4, "punctuality": 5, ...}
    strengths       TEXT,
    improvements    TEXT,
    comments        TEXT,
    goals           JSONB NOT NULL DEFAULT '[]',                    -- [{goal, target_date, status}]
    self_assessment JSONB,
    status          approval_status NOT NULL DEFAULT 'pending',
    acknowledged_by_staff BOOLEAN NOT NULL DEFAULT FALSE,
    acknowledged_at TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ============================================================================
-- END file: 11_hr_and_staff.sql
-- ============================================================================


-- ============================================================================
-- BEGIN file: 12_timetable_and_planning.sql
-- ============================================================================

-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - TIMETABLE & ACADEMIC PLANNING
-- ============================================================================
-- File: 12_timetable_and_planning.sql
-- Description: Weekly timetable, lesson plans, homework, LMS materials
-- ============================================================================

-- ============================================================================
-- PERIOD DEFINITIONS  (bell schedule)
-- ============================================================================
CREATE TABLE period_definitions (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id   UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name        VARCHAR(50) NOT NULL,                               -- Period 1, Lunch, Assembly
    sequence    SMALLINT NOT NULL,
    start_time  TIME NOT NULL,
    end_time    TIME NOT NULL,
    is_break    BOOLEAN NOT NULL DEFAULT FALSE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT chk_period_time CHECK (end_time > start_time),
    CONSTRAINT uq_period UNIQUE (tenant_id, sequence)
);

-- ============================================================================
-- TIMETABLE  (weekly recurring schedule)
-- ============================================================================
CREATE TABLE timetables (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    class_id        UUID NOT NULL REFERENCES classes(id) ON DELETE CASCADE,
    section_id      UUID REFERENCES sections(id),
    academic_year_id UUID NOT NULL REFERENCES academic_years(id),
    day_of_week     day_of_week NOT NULL,
    period_id       UUID NOT NULL REFERENCES period_definitions(id),
    subject_id      UUID REFERENCES subjects(id),                -- NULL for breaks
    teacher_id      UUID REFERENCES users(id),
    room_number     VARCHAR(20),
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_timetable_slot UNIQUE (class_id, section_id, academic_year_id, day_of_week, period_id)
);

COMMENT ON TABLE timetables IS 'Weekly recurring class schedule; one row per class-section-day-period';

-- ============================================================================
-- LESSON PLANS
-- ============================================================================
CREATE TABLE lesson_plans (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    teacher_id          UUID NOT NULL REFERENCES users(id),
    class_id            UUID NOT NULL REFERENCES classes(id),
    section_id          UUID REFERENCES sections(id),
    subject_id          UUID NOT NULL REFERENCES subjects(id),
    academic_year_id    UUID REFERENCES academic_years(id),
    topic               VARCHAR(255) NOT NULL,
    learning_objectives TEXT,
    methodology         TEXT,
    materials           TEXT,
    assessment_plan     TEXT,
    start_date          DATE NOT NULL,
    end_date            DATE NOT NULL,
    actual_completion_date DATE,
    status              VARCHAR(20) NOT NULL DEFAULT 'draft'
                        CHECK (status IN ('draft', 'submitted', 'approved', 'in_progress', 'completed')),
    reviewed_by         UUID REFERENCES users(id),
    review_comments     TEXT,
    attachments         JSONB,                                      -- [{name, url}]
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT chk_lesson_dates CHECK (end_date >= start_date)
);

-- ============================================================================
-- HOMEWORK / ASSIGNMENTS
-- ============================================================================
CREATE TABLE homework (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    teacher_id      UUID NOT NULL REFERENCES users(id),
    class_id        UUID NOT NULL REFERENCES classes(id),
    section_id      UUID REFERENCES sections(id),
    subject_id      UUID NOT NULL REFERENCES subjects(id),
    title           VARCHAR(255) NOT NULL,
    description     TEXT,
    instructions    TEXT,
    due_date        DATE NOT NULL,
    total_marks     NUMERIC(6,2),
    attachment_urls JSONB,                                          -- [{name, url, type}]
    status          homework_status NOT NULL DEFAULT 'draft',
    published_at    TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- HOMEWORK SUBMISSIONS
-- ============================================================================
CREATE TABLE homework_submissions (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    homework_id     UUID NOT NULL REFERENCES homework(id) ON DELETE CASCADE,
    student_id      UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    submission_text TEXT,
    attachment_urls JSONB,
    submitted_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    is_late         BOOLEAN NOT NULL DEFAULT FALSE,
    marks_obtained  NUMERIC(6,2),
    feedback        TEXT,
    graded_by       UUID REFERENCES users(id),
    graded_at       TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_homework_submission UNIQUE (homework_id, student_id)
);

-- ============================================================================
-- LEARNING MATERIALS  (LMS content)
-- ============================================================================
CREATE TABLE learning_materials (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    teacher_id      UUID NOT NULL REFERENCES users(id),
    class_id        UUID REFERENCES classes(id),
    section_id      UUID REFERENCES sections(id),
    subject_id      UUID REFERENCES subjects(id),
    title           VARCHAR(255) NOT NULL,
    description     TEXT,
    material_type   material_type NOT NULL,
    file_url        TEXT,
    external_link   TEXT,
    file_size_bytes BIGINT,
    duration_minutes INTEGER,                                       -- for video content
    is_published    BOOLEAN NOT NULL DEFAULT FALSE,
    sort_order      SMALLINT DEFAULT 0,
    tags            JSONB,
    view_count      INTEGER NOT NULL DEFAULT 0,
    uploaded_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- ONLINE CLASS / VIRTUAL MEETING LINKS
-- ============================================================================
CREATE TABLE online_classes (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    class_id        UUID NOT NULL REFERENCES classes(id),
    section_id      UUID REFERENCES sections(id),
    subject_id      UUID REFERENCES subjects(id),
    teacher_id      UUID NOT NULL REFERENCES users(id),
    title           VARCHAR(255) NOT NULL,
    meeting_url     TEXT NOT NULL,
    platform        VARCHAR(50),                                    -- zoom, google_meet, teams
    scheduled_date  DATE NOT NULL,
    start_time      TIME NOT NULL,
    end_time        TIME,
    recording_url   TEXT,
    is_recurring    BOOLEAN NOT NULL DEFAULT FALSE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ============================================================================
-- END file: 12_timetable_and_planning.sql
-- ============================================================================


-- ============================================================================
-- BEGIN file: 13_administration.sql
-- ============================================================================

-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - ADMINISTRATION
-- ============================================================================
-- File: 13_administration.sql
-- Description: Hostel, inventory, assets, visitors, complaints
-- ============================================================================

-- ============================================================================
-- HOSTELS
-- ============================================================================
CREATE TABLE hostels (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id   UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name        VARCHAR(150) NOT NULL,
    type        VARCHAR(20) CHECK (type IN ('boys', 'girls', 'mixed')),
    total_rooms INTEGER NOT NULL CHECK (total_rooms > 0),
    total_beds  INTEGER,
    address     TEXT,
    warden_id   UUID REFERENCES users(id),
    contact_phone VARCHAR(30),
    is_active   BOOLEAN NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_hostel UNIQUE (tenant_id, name)
);

-- ============================================================================
-- HOSTEL ROOMS
-- ============================================================================
CREATE TABLE hostel_rooms (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    hostel_id           UUID NOT NULL REFERENCES hostels(id) ON DELETE CASCADE,
    room_number         VARCHAR(20) NOT NULL,
    floor               SMALLINT,
    capacity            SMALLINT NOT NULL CHECK (capacity > 0),
    current_occupancy   SMALLINT NOT NULL DEFAULT 0 CHECK (current_occupancy >= 0),
    room_type           room_type NOT NULL DEFAULT 'shared',
    monthly_rent        NUMERIC(10,2),
    amenities           JSONB,                                      -- ["fan","ac","wifi","attached_bath"]
    status              VARCHAR(20) NOT NULL DEFAULT 'available'
                        CHECK (status IN ('available', 'full', 'maintenance', 'closed')),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_hostel_room UNIQUE (hostel_id, room_number),
    CONSTRAINT chk_occupancy CHECK (current_occupancy <= capacity)
);

-- ============================================================================
-- HOSTEL ALLOCATIONS
-- ============================================================================
CREATE TABLE hostel_allocations (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    student_id      UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    hostel_room_id  UUID NOT NULL REFERENCES hostel_rooms(id),
    bed_number      VARCHAR(10),
    allocated_date  DATE NOT NULL,
    leave_date      DATE,
    is_current      BOOLEAN NOT NULL DEFAULT TRUE,
    monthly_rent    NUMERIC(10,2),
    remarks         TEXT,
    allocated_by    UUID REFERENCES users(id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- HOSTEL FEE TRACKING
-- ============================================================================
CREATE TABLE hostel_fees (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    hostel_allocation_id UUID NOT NULL REFERENCES hostel_allocations(id),
    month               SMALLINT NOT NULL CHECK (month BETWEEN 1 AND 12),
    year                SMALLINT NOT NULL,
    amount              NUMERIC(10,2) NOT NULL,
    paid_status         payment_status NOT NULL DEFAULT 'pending',
    payment_date        DATE,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_hostel_fee UNIQUE (hostel_allocation_id, month, year)
);

-- ============================================================================
-- INVENTORY ITEMS
-- ============================================================================
CREATE TABLE inventory_items (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    item_name       VARCHAR(200) NOT NULL,
    item_code       VARCHAR(50),
    category        inventory_category NOT NULL,
    quantity        INTEGER NOT NULL DEFAULT 0 CHECK (quantity >= 0),
    unit            VARCHAR(30) DEFAULT 'piece',
    unit_price      NUMERIC(12,2),
    reorder_level   INTEGER DEFAULT 0,
    supplier_name   VARCHAR(200),
    supplier_contact VARCHAR(30),
    location        VARCHAR(100),
    purchase_date   DATE,
    expiry_date     DATE,
    description     TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_inventory_item UNIQUE (tenant_id, item_code) 
);

-- ============================================================================
-- INVENTORY TRANSACTIONS  (stock in/out)
-- ============================================================================
CREATE TABLE inventory_transactions (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    item_id         UUID NOT NULL REFERENCES inventory_items(id) ON DELETE CASCADE,
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    transaction_type VARCHAR(10) NOT NULL CHECK (transaction_type IN ('in', 'out', 'adjustment')),
    quantity        INTEGER NOT NULL,
    unit_price      NUMERIC(12,2),
    reference       VARCHAR(200),                                   -- PO number, department request, etc.
    remarks         TEXT,
    performed_by    UUID REFERENCES users(id),
    transaction_date DATE NOT NULL DEFAULT CURRENT_DATE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- ASSETS
-- ============================================================================
CREATE TABLE assets (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    asset_name      VARCHAR(200) NOT NULL,
    asset_code      VARCHAR(50),
    asset_type      VARCHAR(100),
    serial_number   VARCHAR(100),
    purchase_date   DATE,
    purchase_price  NUMERIC(14,2),
    warranty_expiry DATE,
    depreciation_rate NUMERIC(5,2),
    current_value   NUMERIC(14,2),
    location        VARCHAR(200),
    assigned_to     UUID REFERENCES users(id),
    department_id   UUID REFERENCES departments(id),
    status          asset_status NOT NULL DEFAULT 'available',
    photo_url       TEXT,
    remarks         TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_asset_code UNIQUE (tenant_id, asset_code)
);

-- ============================================================================
-- VISITORS
-- ============================================================================
CREATE TABLE visitors (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    visitor_name    VARCHAR(150) NOT NULL,
    phone           VARCHAR(30),
    email           VARCHAR(255),
    company         VARCHAR(200),
    whom_to_meet    VARCHAR(150) NOT NULL,
    whom_to_meet_user_id UUID REFERENCES users(id),
    purpose         TEXT NOT NULL,
    id_card_type    VARCHAR(50),
    id_card_number  VARCHAR(100),
    photo_url       TEXT,
    visitor_badge   VARCHAR(20),
    check_in_time   TIMESTAMPTZ NOT NULL DEFAULT now(),
    check_out_time  TIMESTAMPTZ,
    vehicle_number  VARCHAR(30),
    items_carried   TEXT,
    remarks         TEXT,
    approved_by     UUID REFERENCES users(id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- COMPLAINTS / GRIEVANCES
-- ============================================================================
CREATE TABLE complaints (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    raised_by_user_id UUID NOT NULL REFERENCES users(id),
    complaint_type  VARCHAR(100) NOT NULL,                          -- infrastructure, academic, bullying, etc.
    subject         VARCHAR(255) NOT NULL,
    description     TEXT NOT NULL,
    attachment_urls JSONB,
    priority        complaint_priority NOT NULL DEFAULT 'medium',
    assigned_to     UUID REFERENCES users(id),
    status          complaint_status NOT NULL DEFAULT 'open',
    resolution      TEXT,
    resolution_date TIMESTAMPTZ,
    resolved_by     UUID REFERENCES users(id),
    feedback        TEXT,
    feedback_rating SMALLINT CHECK (feedback_rating BETWEEN 1 AND 5),
    escalated_to    UUID REFERENCES users(id),
    escalated_at    TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- COMPLAINT COMMENTS  (discussion thread on a complaint)
-- ============================================================================
CREATE TABLE complaint_comments (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    complaint_id    UUID NOT NULL REFERENCES complaints(id) ON DELETE CASCADE,
    user_id         UUID NOT NULL REFERENCES users(id),
    comment         TEXT NOT NULL,
    attachment_url  TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- EVENTS / CALENDAR
-- ============================================================================
CREATE TABLE events (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    title           VARCHAR(255) NOT NULL,
    description     TEXT,
    event_type      VARCHAR(50),                                    -- holiday, meeting, exam, sports, cultural
    start_datetime  TIMESTAMPTZ NOT NULL,
    end_datetime    TIMESTAMPTZ,
    is_all_day      BOOLEAN NOT NULL DEFAULT FALSE,
    location        VARCHAR(255),
    target_roles    JSONB,                                          -- ["student","teacher","parent"]
    is_holiday      BOOLEAN NOT NULL DEFAULT FALSE,
    created_by      UUID REFERENCES users(id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ============================================================================
-- END file: 13_administration.sql
-- ============================================================================


-- ============================================================================
-- BEGIN file: 14_system_and_audit.sql
-- ============================================================================

-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - SYSTEM, AUDIT & SECURITY
-- ============================================================================
-- File: 14_system_and_audit.sql
-- Description: Audit logs, login sessions, API keys, system settings
-- ============================================================================

-- ============================================================================
-- AUDIT LOG
-- ============================================================================
CREATE TABLE audit_logs (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id   UUID REFERENCES tenants(id) ON DELETE SET NULL,
    user_id     UUID REFERENCES users(id) ON DELETE SET NULL,
    action      VARCHAR(50) NOT NULL,                               -- create, update, delete, login, export, etc.
    module      VARCHAR(100) NOT NULL,                              -- students, finance, attendance, etc.
    entity_type VARCHAR(100),                                       -- table name
    record_id   UUID,
    old_value   JSONB,
    new_value   JSONB,
    description TEXT,
    ip_address  INET,
    user_agent  TEXT,
    request_id  VARCHAR(100),                                       -- correlation ID for tracing
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE audit_logs IS 'Immutable audit trail; high volume â€” consider partitioning by created_at';

-- ============================================================================
-- LOGIN SESSIONS
-- ============================================================================
CREATE TABLE login_sessions (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    tenant_id       UUID REFERENCES tenants(id) ON DELETE CASCADE,
    session_token   VARCHAR(512) NOT NULL UNIQUE,
    refresh_token   VARCHAR(512) UNIQUE,
    login_time      TIMESTAMPTZ NOT NULL DEFAULT now(),
    logout_time     TIMESTAMPTZ,
    expires_at      TIMESTAMPTZ NOT NULL,
    ip_address      INET,
    device_info     JSONB,                                          -- {browser, os, device_type}
    geo_location    VARCHAR(200),
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    terminated_by   VARCHAR(20) CHECK (terminated_by IN ('user', 'admin', 'timeout', 'system')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE login_sessions IS 'Active and historical login sessions; used for session management and security auditing';

-- ============================================================================
-- API KEYS  (per tenant, for external integrations)
-- ============================================================================
CREATE TABLE api_keys (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    key_name        VARCHAR(100) NOT NULL,
    api_key_hash    VARCHAR(255) NOT NULL,                          -- hashed key, never store plaintext
    api_key_prefix  VARCHAR(10) NOT NULL,                           -- first few chars for identification
    permissions     JSONB NOT NULL DEFAULT '{}',                    -- {"students": ["read"], "finance": ["read","write"]}
    rate_limit_rpm  INTEGER DEFAULT 60,                             -- requests per minute
    allowed_ips     JSONB,                                          -- ["1.2.3.4", "10.0.0.0/8"]
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    expires_at      TIMESTAMPTZ,
    last_used_at    TIMESTAMPTZ,
    last_used_ip    INET,
    created_by      UUID REFERENCES users(id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_api_key_name UNIQUE (tenant_id, key_name)
);

COMMENT ON COLUMN api_keys.api_key_hash IS 'bcrypt/argon2 hash of the API key; plaintext never stored';

-- ============================================================================
-- SYSTEM SETTINGS  (global and per-tenant)
-- ============================================================================
CREATE TABLE system_settings (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID REFERENCES tenants(id) ON DELETE CASCADE,  -- NULL = global platform setting
    setting_key     VARCHAR(100) NOT NULL,
    setting_value   JSONB NOT NULL,
    description     TEXT,
    is_public       BOOLEAN NOT NULL DEFAULT FALSE,                 -- visible to non-admin users?
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_system_setting UNIQUE (tenant_id, setting_key)
);

-- ============================================================================
-- IMPORT BATCHES  (tracking CSV/Excel user imports)
-- ============================================================================
CREATE TABLE import_batches (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    batch_id        VARCHAR(100) NOT NULL UNIQUE,
    import_type     VARCHAR(50) NOT NULL,                           -- users, students, staff, etc.
    file_name       VARCHAR(255),
    file_url        TEXT,
    total_rows      INTEGER,
    success_count   INTEGER DEFAULT 0,
    error_count     INTEGER DEFAULT 0,
    error_details   JSONB,                                          -- [{row, field, message}]
    status          VARCHAR(20) NOT NULL DEFAULT 'processing'
                    CHECK (status IN ('processing', 'completed', 'failed', 'partial')),
    imported_by     UUID NOT NULL REFERENCES users(id),
    started_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    completed_at    TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE import_batches IS 'Tracks bulk import operations (CSV/Excel) with row-level error reporting';

-- ============================================================================
-- WEBHOOK CONFIGURATIONS  (outbound webhooks)
-- ============================================================================
CREATE TABLE webhooks (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name            VARCHAR(100) NOT NULL,
    url             TEXT NOT NULL,
    secret          VARCHAR(255),                                   -- HMAC signing secret
    events          JSONB NOT NULL,                                 -- ["student.created", "fee.paid", ...]
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    last_triggered_at TIMESTAMPTZ,
    failure_count   INTEGER NOT NULL DEFAULT 0,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================================
-- WEBHOOK DELIVERY LOG
-- ============================================================================
CREATE TABLE webhook_deliveries (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    webhook_id      UUID NOT NULL REFERENCES webhooks(id) ON DELETE CASCADE,
    event_type      VARCHAR(100) NOT NULL,
    payload         JSONB NOT NULL,
    response_status INTEGER,
    response_body   TEXT,
    duration_ms     INTEGER,
    success         BOOLEAN NOT NULL DEFAULT FALSE,
    attempted_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ============================================================================
-- END file: 14_system_and_audit.sql
-- ============================================================================


