-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - ROW LEVEL SECURITY (RLS)
-- ============================================================================
-- File: 16_rls_policies.sql
-- Description: Row Level Security policies for tenant data isolation
-- ============================================================================

-- ============================================================================
-- APPLICATION ROLE AND SESSION VARIABLE
-- ============================================================================
-- The application must SET the tenant context on every connection:
--   SET app.current_tenant_id = '42';
--   SET app.current_user_id = '7';
--
-- Super admins bypass RLS via a separate DB role or by not setting the variable.
-- ============================================================================

-- Application role (used by the application backend)
DO $$
BEGIN
    IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'sms_admin') THEN
        CREATE ROLE sms_admin NOLOGIN;
    END IF;
END
$$;

-- Grant usage on all tables to app_user
GRANT USAGE ON SCHEMA public TO sms_admin;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO sms_admin;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO sms_admin;

-- ============================================================================
-- HELPER FUNCTION: Get current tenant ID from session
-- ============================================================================
CREATE OR REPLACE FUNCTION current_tenant_id()
RETURNS UUID AS $$
BEGIN
    RETURN NULLIF(current_setting('app.current_tenant_id', TRUE), '')::UUID;
EXCEPTION
    WHEN OTHERS THEN RETURN NULL;
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

-- ============================================================================
-- HELPER FUNCTION: Get current user ID from session
-- ============================================================================
CREATE OR REPLACE FUNCTION current_app_user_id()
RETURNS UUID AS $$
BEGIN
    RETURN NULLIF(current_setting('app.current_user_id', TRUE), '')::UUID;
EXCEPTION
    WHEN OTHERS THEN RETURN NULL;
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

-- ============================================================================
-- HELPER FUNCTION: Check if current user is super admin
-- ============================================================================
CREATE OR REPLACE FUNCTION is_super_admin()
RETURNS BOOLEAN AS $$
BEGIN
    RETURN COALESCE(current_setting('app.is_super_admin', TRUE)::BOOLEAN, FALSE);
EXCEPTION
    WHEN OTHERS THEN RETURN FALSE;
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

-- ============================================================================
-- AUTO-UPDATE updated_at TRIGGER FUNCTION
-- ============================================================================
CREATE OR REPLACE FUNCTION trigger_set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ============================================================================
-- ENABLE RLS ON ALL TENANT-SCOPED TABLES
-- ============================================================================

-- Macro to enable RLS and create policies for a table with tenant_id
-- We'll do this explicitly for each table:

-- ------------- TENANTS ---------------
ALTER TABLE tenants ENABLE ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON tenants
    FOR ALL
    TO sms_admin
    USING (is_super_admin() OR id = current_tenant_id());

