-- ============================================================================
-- APPLY updated_at TRIGGERS TO ALL MUTABLE TABLES
-- ============================================================================
DO $$
DECLARE
    tbl TEXT;
    tbl_list TEXT[] := ARRAY[
        'subscription_plans', 'tenants', 'tenant_settings',
        'roles', 'users', 'academic_years', 'grades', 'departments',
        'classes', 'sections', 'subjects', 'class_subjects',
        'parents', 'students', 'student_health_records',
        'student_attendance', 'teacher_attendance', 'leave_requests', 'leave_balances',
        'grade_systems', 'exams', 'exam_timetables', 'marks_entries', 'results',
        'report_card_templates',
        'fee_structures', 'fee_invoices', 'fee_collections', 'online_payments',
        'scholarships',
        'announcements', 'messages',
        'transport_routes', 'vehicles', 'drivers',
        'student_route_allocations', 'transport_fees',
        'library_catalog', 'book_issues', 'library_fines', 'library_settings',
        'staff', 'payroll', 'performance_evaluations',
        'period_definitions', 'timetables', 'lesson_plans', 'homework',
        'homework_submissions', 'learning_materials', 'online_classes',
        'hostels', 'hostel_rooms', 'hostel_allocations', 'hostel_fees',
        'inventory_items', 'assets', 'complaints', 'events',
        'login_sessions', 'api_keys', 'system_settings', 'webhooks',
        'message_templates', 'biometric_devices'
    ];
BEGIN
    FOREACH tbl IN ARRAY tbl_list LOOP
        EXECUTE format(
            'CREATE TRIGGER set_updated_at BEFORE UPDATE ON %I
             FOR EACH ROW EXECUTE FUNCTION trigger_set_updated_at()',
            tbl
        );
    END LOOP;
END
$$;


