-- Grant all permissions to Super Admin
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id
FROM roles r
CROSS JOIN permissions p
WHERE r.slug = 'super_admin' AND r.tenant_id IS NULL;

-- ============================================================================
-- FUNCTION: Seed default roles for a new tenant
-- ============================================================================
CREATE OR REPLACE FUNCTION seed_tenant_roles(p_tenant_id UUID)
RETURNS VOID AS $$
DECLARE
    v_role_id UUID;
BEGIN
    -- -------------------------------------------------------------------------
    -- Admin  (full access within tenant)
    -- -------------------------------------------------------------------------
    INSERT INTO roles (tenant_id, name, slug, description, is_system)
    VALUES (p_tenant_id, 'Admin', 'admin', 'Tenant administrator with full access', TRUE)
    RETURNING id INTO v_role_id;

    INSERT INTO role_permissions (role_id, permission_id)
    SELECT v_role_id, id FROM permissions;

    -- -------------------------------------------------------------------------
    -- Principal  (manages academics, staff, and operations; no system settings)
    -- -------------------------------------------------------------------------
    INSERT INTO roles (tenant_id, name, slug, description, is_system)
    VALUES (p_tenant_id, 'Principal', 'principal', 'School principal with full academic and HR oversight', TRUE)
    RETURNING id INTO v_role_id;

    INSERT INTO role_permissions (role_id, permission_id)
    SELECT v_role_id, p.id FROM permissions p
    WHERE (p.module, p.action) IN (
        ('students','view'), ('students','create'), ('students','edit'), ('students','export'),
        ('attendance','view'), ('attendance','create'), ('attendance','edit'), ('attendance','export'), ('attendance','approve'),
