-- ============================================================================
-- TRIGGERS: Module enablement and Studentâ†’User linkage
-- ============================================================================

-- ============================================================================
-- TRIGGER: Sync modules from subscription plan to tenant_module_access
-- ============================================================================
-- Whenever a tenant is created or subscription changes, automatically populate
-- the tenant_module_access table based on the subscription plan's features
CREATE OR REPLACE FUNCTION fn_sync_modules_from_subscription()
RETURNS TRIGGER AS $$
DECLARE
    v_feature_count INT;
BEGIN
    -- Only process if subscription_plan_id changed or new tenant
    IF TG_OP = 'INSERT' OR NEW.subscription_plan_id != OLD.subscription_plan_id THEN
        
        -- Delete old module access records for this tenant
        DELETE FROM tenant_module_access 
        WHERE tenant_id = NEW.id;

        -- Insert new records based on subscription plan's features
        IF NEW.subscription_plan_id IS NOT NULL THEN
            INSERT INTO tenant_module_access (tenant_id, module_name, is_enabled, enabled_at)
            SELECT 
                NEW.id,
                key,
                (value::text = 'true'),
                CASE WHEN (value::text = 'true') THEN now() ELSE NULL END
            FROM subscription_plans sp
            CROSS JOIN LATERAL jsonb_each(sp.features)
            WHERE sp.id = NEW.subscription_plan_id;
        ELSE
            -- Trial or free tier: enable core modules only
            INSERT INTO tenant_module_access (tenant_id, module_name, is_enabled, enabled_at)
            VALUES 
                (NEW.id, 'students', TRUE, now()),
                (NEW.id, 'attendance', TRUE, now()),
                (NEW.id, 'examination', TRUE, now()),
                (NEW.id, 'results', TRUE, now()),
                (NEW.id, 'finance', TRUE, now()),
                (NEW.id, 'fee_collection', TRUE, now()),
                (NEW.id, 'communication', FALSE, now()),
                (NEW.id, 'transport', FALSE, now()),
                (NEW.id, 'hostel', FALSE, now()),
                (NEW.id, 'library', TRUE, now()),
                (NEW.id, 'hr', TRUE, now()),
                (NEW.id, 'payroll', FALSE, now()),
                (NEW.id, 'timetable', TRUE, now()),
                (NEW.id, 'lesson_plan', TRUE, now()),
                (NEW.id, 'homework', TRUE, now()),
                (NEW.id, 'online_classes', FALSE, now()),
                (NEW.id, 'learning_materials', TRUE, now()),
                (NEW.id, 'inventory', TRUE, now()),
                (NEW.id, 'assets', TRUE, now()),
                (NEW.id, 'visitors', TRUE, now()),
                (NEW.id, 'complaints', TRUE, now()),
                (NEW.id, 'events', TRUE, now()),
                (NEW.id, 'reports', TRUE, now()),
                (NEW.id, 'user_management', TRUE, now()),
                (NEW.id, 'settings', TRUE, now()),
                (NEW.id, 'audit', TRUE, now()),
                (NEW.id, 'api_keys', FALSE, now());
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_sync_modules_from_subscription
AFTER INSERT OR UPDATE OF subscription_plan_id ON tenants
FOR EACH ROW
EXECUTE FUNCTION fn_sync_modules_from_subscription();

COMMENT ON FUNCTION fn_sync_modules_from_subscription IS
'Automatically syncs tenant_module_access when subscription plan changes';

-- ============================================================================
-- TRIGGER: Auto-create user when student is created
-- ============================================================================
-- When a new student record is inserted without a user_id,
-- automatically create a user account and assign Student role
CREATE OR REPLACE FUNCTION fn_create_user_for_student()
RETURNS TRIGGER AS $$
DECLARE
    v_user_id UUID;
    v_student_role_id UUID;
    v_default_password VARCHAR;
BEGIN
    -- Only auto-create if user_id is not provided
    IF NEW.user_id IS NULL THEN
        
        -- Generate a temporary password
        v_default_password := substring(md5(random()::text), 1, 12);

        -- Create user record with auto-generated credentials
        INSERT INTO users (
            tenant_id,
            username,
            email,
            password_hash,
            first_name,
            last_name,
            status,
            created_offline_at
        ) VALUES (
            NEW.tenant_id,
            'student_' || substring(NEW.id::text, 1, 8),  -- first 8 chars of student UUID
            NEW.id::text || '@' || NEW.tenant_id::text,   -- placeholder: studentid@tenantid
            crypt(v_default_password, gen_salt('bf')),
            NEW.first_name,
            NEW.last_name,
            'active',
            now()
        ) RETURNING id INTO v_user_id;

        -- Update student with newly created user
        NEW.user_id := v_user_id;

        -- Find the Student role for this tenant
        SELECT id INTO v_student_role_id
        FROM roles
        WHERE tenant_id = NEW.tenant_id
          AND slug = 'student'
          AND is_system = TRUE
        LIMIT 1;

        -- Assign Student role if found
        IF v_student_role_id IS NOT NULL THEN
            INSERT INTO user_roles (user_id, role_id)
            VALUES (v_user_id, v_student_role_id)
            ON CONFLICT (user_id, role_id) DO NOTHING;
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_create_user_for_student
BEFORE INSERT ON students
FOR EACH ROW
EXECUTE FUNCTION fn_create_user_for_student();

COMMENT ON FUNCTION fn_create_user_for_student IS
'Automatically creates a user account when a student is created without one. Links them and assigns Student role.';


