-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - VIEWS FOR ANALYTICS & REPORTING
-- ============================================================================
-- File: 18_views.sql
-- Description: Materialized and regular views for dashboards and reports
-- ============================================================================

-- ============================================================================
-- STUDENT ATTENDANCE SUMMARY  (per student per month)
-- ============================================================================
CREATE VIEW v_student_attendance_summary AS
SELECT
    s.tenant_id,
    sa.student_id,
    s.first_name || ' ' || COALESCE(s.last_name, '') AS student_name,
    s.admission_number,
    sa.class_id,
    c.name AS class_name,
    EXTRACT(YEAR FROM sa.date)::INT AS year,
    EXTRACT(MONTH FROM sa.date)::INT AS month,
    COUNT(*) FILTER (WHERE sa.status = 'present') AS present_days,
    COUNT(*) FILTER (WHERE sa.status = 'absent') AS absent_days,
    COUNT(*) FILTER (WHERE sa.status = 'late') AS late_days,
    COUNT(*) FILTER (WHERE sa.status = 'half_day') AS half_days,
    COUNT(*) AS total_days,
    ROUND(
        COUNT(*) FILTER (WHERE sa.status IN ('present', 'late', 'half_day'))::NUMERIC / NULLIF(COUNT(*), 0) * 100, 2
    ) AS attendance_percentage
FROM student_attendance sa
JOIN students s ON s.id = sa.student_id
JOIN classes c ON c.id = sa.class_id
GROUP BY s.tenant_id, sa.student_id, s.first_name, s.last_name, s.admission_number,
         sa.class_id, c.name,
         EXTRACT(YEAR FROM sa.date), EXTRACT(MONTH FROM sa.date);

-- ============================================================================
-- FEE COLLECTION SUMMARY  (per student, outstanding vs paid)
-- ============================================================================
CREATE VIEW v_fee_summary AS
SELECT
    fi.tenant_id,
    fi.student_id,
    s.first_name || ' ' || COALESCE(s.last_name, '') AS student_name,
    s.admission_number,
    s.class_id,
    c.name AS class_name,
    SUM(fi.net_amount) AS total_fee,
    COALESCE(SUM(fc.total_paid), 0) AS total_paid,
    SUM(fi.net_amount) - COALESCE(SUM(fc.total_paid), 0) AS outstanding,
    COUNT(*) FILTER (WHERE fi.status = 'pending') AS pending_invoices,
    COUNT(*) FILTER (WHERE fi.status = 'completed') AS paid_invoices
FROM fee_invoices fi
JOIN students s ON s.id = fi.student_id
JOIN classes c ON c.id = s.class_id
LEFT JOIN LATERAL (
    SELECT SUM(amount_paid) AS total_paid
    FROM fee_collections
    WHERE fee_invoice_id = fi.id AND NOT cancelled
) fc ON TRUE
GROUP BY fi.tenant_id, fi.student_id, s.first_name, s.last_name,
         s.admission_number, s.class_id, c.name;

-- ============================================================================
-- EXAM RESULTS ANALYTICS  (class-level aggregation)
-- ============================================================================
CREATE VIEW v_exam_class_analytics AS
SELECT
    e.tenant_id,
    r.exam_id,
    e.name AS exam_name,
    r.class_id,
    cl.name AS class_name,
    COUNT(r.id) AS total_students,
    ROUND(AVG(r.percentage), 2) AS avg_percentage,
    MAX(r.percentage) AS max_percentage,
    MIN(r.percentage) AS min_percentage,
    ROUND(STDDEV(r.percentage), 2) AS stddev_percentage,
    COUNT(*) FILTER (WHERE r.status = 'pass') AS pass_count,
    COUNT(*) FILTER (WHERE r.status = 'fail') AS fail_count,
    ROUND(
        COUNT(*) FILTER (WHERE r.status = 'pass')::NUMERIC / NULLIF(COUNT(*), 0) * 100, 2
    ) AS pass_percentage
FROM results r
JOIN exams e ON e.id = r.exam_id
JOIN classes cl ON cl.id = r.class_id
GROUP BY e.tenant_id, r.exam_id, e.name, r.class_id, cl.name;

-- ============================================================================
-- TEACHER WORKLOAD  (periods per week)
-- ============================================================================
CREATE VIEW v_teacher_workload AS
SELECT
    t.tenant_id,
    t.teacher_id,
    u.first_name || ' ' || COALESCE(u.last_name, '') AS teacher_name,
    COUNT(DISTINCT t.id) AS total_periods_per_week,
    COUNT(DISTINCT t.class_id) AS classes_assigned,
    COUNT(DISTINCT t.subject_id) AS subjects_assigned,
    ARRAY_AGG(DISTINCT t.day_of_week ORDER BY t.day_of_week) AS active_days
FROM timetables t
JOIN users u ON u.id = t.teacher_id
WHERE t.is_active = TRUE AND t.subject_id IS NOT NULL
GROUP BY t.tenant_id, t.teacher_id, u.first_name, u.last_name;

-- ============================================================================
-- LIBRARY OVERDUE BOOKS
-- ============================================================================
CREATE VIEW v_library_overdue AS
SELECT
    bi.tenant_id,
    bi.id AS book_issue_id,
    lc.book_title,
    lc.author,
    bi.student_id,
    s.first_name || ' ' || COALESCE(s.last_name, '') AS borrower_name,
    s.admission_number,
    bi.issue_date,
    bi.due_date,
    CURRENT_DATE - bi.due_date AS overdue_days,
    COALESCE(ls.fine_per_day, 1.00) * (CURRENT_DATE - bi.due_date) AS estimated_fine
FROM book_issues bi
JOIN library_catalog lc ON lc.id = bi.book_id
LEFT JOIN students s ON s.id = bi.student_id
LEFT JOIN library_settings ls ON ls.tenant_id = bi.tenant_id
WHERE bi.status = 'issued'
  AND bi.due_date < CURRENT_DATE;

-- ============================================================================
-- HOSTEL OCCUPANCY OVERVIEW
-- ============================================================================
CREATE VIEW v_hostel_occupancy AS
SELECT
    h.tenant_id,
    h.id AS hostel_id,
    h.name AS hostel_name,
    h.type,
    COUNT(hr.id) AS total_rooms,
    SUM(hr.capacity) AS total_capacity,
    SUM(hr.current_occupancy) AS current_occupancy,
    SUM(hr.capacity) - SUM(hr.current_occupancy) AS available_beds,
    ROUND(
        SUM(hr.current_occupancy)::NUMERIC / NULLIF(SUM(hr.capacity), 0) * 100, 2
    ) AS occupancy_percentage
FROM hostels h
JOIN hostel_rooms hr ON hr.hostel_id = h.id
WHERE h.is_active = TRUE
GROUP BY h.tenant_id, h.id, h.name, h.type;

-- ============================================================================
-- PAYROLL SUMMARY  (monthly totals per tenant)
-- ============================================================================
CREATE VIEW v_payroll_monthly_summary AS
SELECT
    p.tenant_id,
    p.year,
    p.month,
    COUNT(*) AS staff_count,
    SUM(p.gross_salary) AS total_gross,
    SUM(p.total_deductions) AS total_deductions,
    SUM(p.net_salary) AS total_net,
    COUNT(*) FILTER (WHERE p.status = 'paid') AS paid_count,
    COUNT(*) FILTER (WHERE p.status = 'draft') AS draft_count
FROM payroll p
GROUP BY p.tenant_id, p.year, p.month;

-- ============================================================================
-- DAILY ATTENDANCE DASHBOARD  (today's snapshot)
-- ============================================================================
CREATE VIEW v_daily_attendance_dashboard AS
SELECT
    sa.class_id,
    c.tenant_id,
    c.name AS class_name,
    sa.date,
    COUNT(*) AS total_students,
    COUNT(*) FILTER (WHERE sa.status = 'present') AS present,
    COUNT(*) FILTER (WHERE sa.status = 'absent') AS absent,
    COUNT(*) FILTER (WHERE sa.status = 'late') AS late,
    ROUND(
        COUNT(*) FILTER (WHERE sa.status IN ('present', 'late'))::NUMERIC / NULLIF(COUNT(*), 0) * 100, 2
    ) AS attendance_rate
FROM student_attendance sa
JOIN classes c ON c.id = sa.class_id
GROUP BY sa.class_id, c.tenant_id, c.name, sa.date;

-- ============================================================================
-- TRANSPORT ROUTE UTILIZATION
-- ============================================================================
CREATE VIEW v_transport_utilization AS
SELECT
    tr.tenant_id,
    tr.id AS route_id,
    tr.route_name,
    v.vehicle_number,
    v.capacity AS vehicle_capacity,
    COUNT(sra.id) FILTER (WHERE sra.is_active) AS active_students,
    ROUND(
        COUNT(sra.id) FILTER (WHERE sra.is_active)::NUMERIC / NULLIF(v.capacity, 0) * 100, 2
    ) AS utilization_percentage
FROM transport_routes tr
LEFT JOIN vehicles v ON v.route_id = tr.id AND v.status = 'active'
LEFT JOIN student_route_allocations sra ON sra.route_id = tr.id
WHERE tr.is_active = TRUE
GROUP BY tr.tenant_id, tr.id, tr.route_name, v.vehicle_number, v.capacity;


-- ============================================================================
-- END file: 18_views.sql
