-- ============================================================================
-- SCHOOL MANAGEMENT SYSTEM - AUTH & SECURITY ENHANCEMENTS
-- ============================================================================
-- File: 20_auth_security_enhancements.sql
-- Description: Aligns SMS schema with production auth/security architecture
--              based on bfui-be-core patterns:
--              - Identity Providers (OAuth2/LDAP/SAML/Local)
--              - Enhanced users table (lockout, IDP, user class)
--              - Password history & reset tokens
--              - JWT signing keys (asymmetric key management)
--              - Security settings (per-tenant password/session policy)
--              - MFA configuration
--              - IP allowlist (ACL)
--              - Enhanced audit logs (versioned, JSONB old/new)
--              - Enhanced login sessions (JTI-based session tracking)
-- ============================================================================

-- ============================================================================
-- 1. IDENTITY PROVIDERS
-- Supports: local, Google, GitHub, Microsoft/Entra, LDAP, SAML
-- Multiple IDPs can exist per tenant (e.g., 2 Google Workspace setups)
-- ============================================================================
CREATE TABLE identity_providers (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID REFERENCES tenants(id) ON DELETE CASCADE,   -- NULL = platform-wide IDP
    name            VARCHAR(256) NOT NULL UNIQUE,                     -- e.g. "Google Workspace - School"
    type            identity_provider_type NOT NULL DEFAULT 'local',  -- google, github, ldap, saml, entra

    -- OAuth2 fields (Google, GitHub, Microsoft, Entra)
    client_id       VARCHAR(256),                                     -- OAuth2 client ID
    client_secret   VARCHAR(256),                                     -- OAuth2 client secret (encrypted at rest)
    redirect_url    VARCHAR(512),                                     -- OAuth2 redirect/callback URL
    scopes          JSONB DEFAULT '["email","profile"]',              -- OAuth2 scopes requested

    -- Dynamic attributes: LDAP base_dn, SAML endpoints, etc.
    -- For LDAP: { "base_dn": "dc=school,dc=com", "bind_dn": "...", "server": "ldap://..." }
    -- For SAML: { "metadata_url": "...", "entity_id": "..." }
    -- For OAuth2: { "auth_url": "...", "token_url": "...", "device_auth_url": "...", "auth_style": 0 }
    attributes      JSONB NOT NULL DEFAULT '{}',

    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE identity_providers IS
'Defines authentication sources per tenant. Each tenant can have multiple IDPs (e.g., Google + LDAP).';
COMMENT ON COLUMN identity_providers.client_secret IS
'SENSITIVE: OAuth2 client secret. Must be encrypted at rest before storage.';
COMMENT ON COLUMN identity_providers.attributes IS
'Dynamic IDP-specific config: LDAP base_dn/server/bind_dn, SAML metadata_url, OAuth2 endpoint URLs.';

CREATE INDEX idx_identity_providers_tenant ON identity_providers (tenant_id);
CREATE INDEX idx_identity_providers_type   ON identity_providers (type) WHERE is_active = TRUE;

-- ============================================================================
-- 2. ENHANCE USERS TABLE
-- ============================================================================

-- 2a. Authentication type
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS user_type          user_type NOT NULL DEFAULT 'local',
    ADD COLUMN IF NOT EXISTS identity_provider  VARCHAR(100) NOT NULL DEFAULT 'local';

-- 2b. IDP FK
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS identity_provider_id UUID REFERENCES identity_providers(id) ON DELETE SET NULL;

-- 2c. OAuth external user ID
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS oauth_id VARCHAR(256);

CREATE UNIQUE INDEX idx_users_oauth_id ON users (oauth_id) WHERE oauth_id IS NOT NULL;
DROP INDEX IF EXISTS idx_users_oauth_id;


-- 2d. User privilege class
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS user_class INTEGER NOT NULL DEFAULT 1
        CONSTRAINT chk_user_class CHECK (user_class BETWEEN 1 AND 4);

-- 2e. Granular account states
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS is_locked   BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN IF NOT EXISTS is_disabled BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN IF NOT EXISTS locked_at   TIMESTAMPTZ;

-- 2f. Failed login tracking
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS failed_login_attempts               INTEGER NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS last_failed_login_at                TIMESTAMPTZ,
    ADD COLUMN IF NOT EXISTS failed_login_timestamps             JSONB NOT NULL DEFAULT '[]',
    ADD COLUMN IF NOT EXISTS failed_login_attempts_since_last_signin INTEGER NOT NULL DEFAULT 0;

-- 2g. Password management flags
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS force_password_reset BOOLEAN NOT NULL DEFAULT FALSE;

-- 2h. Previous login
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS previous_login_at TIMESTAMPTZ;

-- 2i. Role change tracking
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS role_updated_at TIMESTAMPTZ;

-- 2j. Display names
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS friendly_name VARCHAR(100),
    ADD COLUMN IF NOT EXISTS formal_name   VARCHAR(100);

-- 2k. User-specific JSONB fields
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS preferences JSONB NOT NULL DEFAULT '{}',
    ADD COLUMN IF NOT EXISTS log_events  JSONB NOT NULL DEFAULT '{}';

-- Indexes for new columns
CREATE INDEX idx_users_user_type           ON users (user_type);
CREATE INDEX idx_users_is_locked           ON users (is_locked)   WHERE is_locked = TRUE;
CREATE INDEX idx_users_is_disabled         ON users (is_disabled) WHERE is_disabled = TRUE;
CREATE INDEX idx_users_force_password_reset ON users (force_password_reset) WHERE force_password_reset = TRUE;
CREATE INDEX idx_users_identity_provider_id ON users (identity_provider_id);

-- ============================================================================
-- 3. PASSWORD HISTORY
-- ============================================================================
CREATE TABLE password_history (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    password_hash VARCHAR(256) NOT NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE password_history IS
'Stores hashed previous passwords to enforce password reuse prevention. Only most recent N entries are kept.';

CREATE INDEX idx_password_history_user ON password_history (user_id, created_at DESC);

-- ============================================================================
-- 4. PASSWORD RESET TOKENS
-- ============================================================================
CREATE TABLE password_reset_tokens (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash      VARCHAR(256) NOT NULL,
    expires_at      TIMESTAMPTZ NOT NULL DEFAULT (now() + INTERVAL '24 hours'),
    is_used         BOOLEAN NOT NULL DEFAULT FALSE,
    used_at         TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE password_reset_tokens IS
'One-use password reset tokens. Token hash stored (never plaintext). Expires after 24h by default.';

CREATE INDEX idx_password_reset_user      ON password_reset_tokens (user_id);
CREATE INDEX idx_password_reset_expires   ON password_reset_tokens (expires_at) WHERE is_used = FALSE;

-- ============================================================================
-- 5. JWT SIGNING KEYS
-- ============================================================================
CREATE TABLE jwt_signing_keys (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID REFERENCES tenants(id) ON DELETE CASCADE,
    algorithm       jwt_algorithm NOT NULL DEFAULT 'RS256',
    issuer_id       VARCHAR(256) NOT NULL,
    public_key      TEXT NOT NULL,
    private_key     TEXT NOT NULL,
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    rotated_at      TIMESTAMPTZ,
    expires_at      TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE jwt_signing_keys IS
'Asymmetric JWT signing keys (RSA-4096/ECC). Only one active key per tenant at a time. Old keys kept for verification.';

CREATE UNIQUE INDEX idx_jwt_signing_active ON jwt_signing_keys (tenant_id, is_active)
    WHERE is_active = TRUE;
CREATE INDEX idx_jwt_signing_issuer ON jwt_signing_keys (issuer_id);

-- ============================================================================
-- 6. SECURITY SETTINGS
-- ============================================================================
CREATE TABLE security_settings (
    id                              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id                       UUID UNIQUE REFERENCES tenants(id) ON DELETE CASCADE,

    password_min_length             INTEGER NOT NULL DEFAULT 8
        CONSTRAINT chk_pwd_min_len CHECK (password_min_length BETWEEN 1 AND 128),
    password_max_length             INTEGER NOT NULL DEFAULT 128
        CONSTRAINT chk_pwd_max_len CHECK (password_max_length BETWEEN 8 AND 256),
    password_min_uppercase          INTEGER NOT NULL DEFAULT 1  CONSTRAINT chk_pwd_upper  CHECK (password_min_uppercase  >= 0),
    password_min_lowercase          INTEGER NOT NULL DEFAULT 1  CONSTRAINT chk_pwd_lower  CHECK (password_min_lowercase  >= 0),
    password_min_numbers            INTEGER NOT NULL DEFAULT 1  CONSTRAINT chk_pwd_num    CHECK (password_min_numbers    >= 0),
    password_min_special_chars      INTEGER NOT NULL DEFAULT 1  CONSTRAINT chk_pwd_spec   CHECK (password_min_special_chars >= 0),

    max_failed_login_attempts       INTEGER NOT NULL DEFAULT 5
        CONSTRAINT chk_max_failed CHECK (max_failed_login_attempts BETWEEN 1 AND 100),
    lockout_observation_window_mins INTEGER NOT NULL DEFAULT 30
        CONSTRAINT chk_lockout_window CHECK (lockout_observation_window_mins > 0),
    lockout_duration_mins           INTEGER NOT NULL DEFAULT 30
        CONSTRAINT chk_lockout_dur CHECK (lockout_duration_mins >= 0),

    password_history_count          INTEGER NOT NULL DEFAULT 5
        CONSTRAINT chk_pwd_hist CHECK (password_history_count >= 0),
    password_expiry_days            INTEGER NOT NULL DEFAULT 90
        CONSTRAINT chk_pwd_expiry CHECK (password_expiry_days >= 0),
    force_password_change_on_first  BOOLEAN NOT NULL DEFAULT TRUE,

    max_concurrent_sessions         INTEGER NOT NULL DEFAULT 3
        CONSTRAINT chk_max_sessions CHECK (max_concurrent_sessions BETWEEN 1 AND 50),
    inactivity_logout_mins          INTEGER NOT NULL DEFAULT 30
        CONSTRAINT chk_inactivity CHECK (inactivity_logout_mins > 1),
    access_token_ttl_mins           INTEGER NOT NULL DEFAULT 60
        CONSTRAINT chk_access_ttl CHECK (access_token_ttl_mins BETWEEN 1 AND 1440),
    refresh_token_ttl_days          INTEGER NOT NULL DEFAULT 7
        CONSTRAINT chk_refresh_ttl CHECK (refresh_token_ttl_days BETWEEN 1 AND 365),

    mfa_required                    BOOLEAN NOT NULL DEFAULT FALSE,
    mfa_methods                     JSONB NOT NULL DEFAULT '["totp"]',

    created_at                      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at                      TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE security_settings IS
'Per-tenant security policy: password complexity, account lockout, session limits, MFA. NULL tenant = platform default.';

-- ============================================================================
-- 7. MFA CONFIGURATIONS
-- ============================================================================
CREATE TABLE mfa_configs (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    method          mfa_method NOT NULL DEFAULT 'totp',
    secret          VARCHAR(256),
    is_active       BOOLEAN NOT NULL DEFAULT FALSE,
    verified_at     TIMESTAMPTZ,
    backup_codes    JSONB,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_user_mfa_method UNIQUE (user_id, method)
);

COMMENT ON TABLE mfa_configs IS
'User MFA method enrollment. One row per user per method. TOTP secret encrypted at rest.';

CREATE INDEX idx_mfa_configs_user    ON mfa_configs (user_id);
CREATE INDEX idx_mfa_configs_active  ON mfa_configs (user_id, is_active) WHERE is_active = TRUE;

-- ============================================================================
-- 8. IP ALLOWLIST
-- ============================================================================
CREATE TABLE ip_allowlist (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID REFERENCES tenants(id) ON DELETE CASCADE,
    ip_address      CIDR NOT NULL,
    label           VARCHAR(100),
    is_allowed      BOOLEAN NOT NULL DEFAULT TRUE,
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    created_by      UUID REFERENCES users(id) ON DELETE SET NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE ip_allowlist IS
'IP/CIDR-based access control. is_allowed=TRUE means whitelist, FALSE means blocklist. Platform-wide rules have tenant_id=NULL.';

CREATE INDEX idx_ip_allowlist_tenant  ON ip_allowlist (tenant_id) WHERE is_active = TRUE;
CREATE INDEX idx_ip_allowlist_cidr    ON ip_allowlist USING GIST (ip_address inet_ops) WHERE is_active = TRUE;

-- ============================================================================
-- 9. ENHANCE LOGIN SESSIONS
-- ============================================================================
ALTER TABLE login_sessions
    ADD COLUMN IF NOT EXISTS jti           VARCHAR(256) UNIQUE,
    ADD COLUMN IF NOT EXISTS login_method  VARCHAR(50);

CREATE INDEX idx_login_sessions_jti ON login_sessions (jti) WHERE jti IS NOT NULL;

-- ============================================================================
-- 10. ENHANCE AUDIT LOGS
-- ============================================================================
ALTER TABLE audit_logs
    ADD COLUMN IF NOT EXISTS record_version  INTEGER NOT NULL DEFAULT 1,
    ADD COLUMN IF NOT EXISTS access_scope    JSONB,
    ADD COLUMN IF NOT EXISTS service_name    VARCHAR(128),
    ADD COLUMN IF NOT EXISTS change_reason   VARCHAR(512),
    ADD COLUMN IF NOT EXISTS deleted_at      TIMESTAMPTZ;

CREATE INDEX idx_audit_logs_record_version
    ON audit_logs (entity_type, record_id, record_version DESC)
    WHERE deleted_at IS NULL;

-- ============================================================================
-- 11. SEED: Platform-level global security settings
-- ============================================================================
INSERT INTO security_settings (
    tenant_id,
    password_min_length, password_max_length,
    password_min_uppercase, password_min_lowercase,
    password_min_numbers, password_min_special_chars,
    max_failed_login_attempts, lockout_observation_window_mins, lockout_duration_mins,
    password_history_count, password_expiry_days, force_password_change_on_first,
    max_concurrent_sessions, inactivity_logout_mins,
    access_token_ttl_mins, refresh_token_ttl_days,
    mfa_required
) VALUES (
    NULL,   -- platform-wide default
    8, 128,
    1, 1, 1, 1,
    5, 30, 30,
    5, 90, TRUE,
    3, 30,
    60, 7,
    FALSE
) ON CONFLICT DO NOTHING;

-- ============================================================================
-- 12. SEED: Local identity provider
-- ============================================================================
INSERT INTO identity_providers (id, tenant_id, name, type, is_active)
VALUES (
